}
.btn:hover { transform: translateY(-2px); box-shadow: 0 6px 0 var(--btn-edge), 0 12px 20px rgba(90, 43, 64, .17); filter: saturate(1.05); }
.btn:active { transform: translateY(3px); box-shadow: 0 1px 0 var(--btn-edge), 0 3px 8px rgba(90, 43, 64, .13); }
.btn .icon { width: 17px; height: 17px; }
.btn:disabled, .btn[aria-disabled="true"] {
  cursor: not-allowed; filter: grayscale(.55); opacity: .55;
  transform: none; box-shadow: 0 3px 0 var(--btn-edge);
}
.btn-primary {
  --btn-bg: linear-gradient(180deg, #ff9db3, #ef7096);
  --btn-ink: #fff;
  --btn-edge: #a93e62;
  text-shadow: 0 1px 0 rgba(99, 33, 55, .3);
}
.btn-cream { --btn-bg: #fff6e6; --btn-ink: #66445c; --btn-edge: #d7b79f; }
.btn-mint { --btn-bg: #a7dfcd; --btn-ink: #27554c; --btn-edge: #5f9f8e; }
.btn-violet { --btn-bg: #c2b2ea; --btn-ink: #44336c; --btn-edge: #806ab8; }
.btn-danger { --btn-bg: #ef9aa5; --btn-ink: #692536; --btn-edge: #b65363; }
.btn-ghost {
  --btn-bg: rgba(255,255,255,.55); --btn-ink: #6f5269; --btn-edge: rgba(115, 78, 104, .22);
  border-color: rgba(81,59,81,.22); box-shadow: 0 3px 0 var(--btn-edge);
}
.btn-sm { min-height: 34px; padding: 7px 12px; font-size: 11px; border-width: 1.5px; box-shadow: 0 3px 0 var(--btn-edge); }
.btn-xs { min-height: 29px; padding: 5px 9px; font-size: 10px; border-width: 1.5px; box-shadow: 0 2px 0 var(--btn-edge); }
.btn-lg { min-height: 50px; padding: 13px 23px; font-size: 16px; }
.btn-block { width: 100%; }
.btn-hero { min-width: 154px; min-height: 52px; font-size: 17px; letter-spacing: .03em; }
.btn[data-action="flirt"] { --btn-bg: linear-gradient(180deg, #ffc0cf, #f293ae); --btn-ink: #6b2a42; --btn-edge: #b95577; }
.btn[data-action="gift"] { --btn-bg: linear-gradient(180deg, #ffe18b, #f5c55b); --btn-ink: #65440d; --btn-edge: #ba8a2a; }
.icon-btn {
  width: 40px; height: 40px; border-radius: 50%;
  border: 1.5px solid rgba(81,59,81,.16);
  background: #fffaf3;
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--ink-soft);
  box-shadow: 0 2px 0 rgba(81,59,81,.1);
  transition: .16s ease;
}
.icon-btn:hover { background: #fff; transform: translateY(-1px); color: var(--pink-deep); }
.icon-btn:active { transform: translateY(1px); }
.text-btn {
  border: 0; background: none; padding: 4px; font-size: 11px; font-weight: 700;
  color: var(--ink-soft); text-decoration: underline; text-decoration-color: rgba(117,98,118,.35);
  text-underline-offset: 3px;
}
.text-btn:hover { color: var(--pink-deep); }
.text-btn.danger { color: #ae5362; }
.link-btn { border: 0; background: none; padding: 0; color: var(--pink-deep); font-weight: 800; text-decoration: underline; text-underline-offset: 3px; font-size: inherit; }
.back-btn { display: inline-flex; gap: 8px; align-items: center; font-size: 12px; font-weight: 800; color: var(--ink-soft); border: 0; background: none; padding: 5px 0; }
.back-btn:hover { color: var(--pink-deep); }

/* ---------- Panels, cards, meters ---------- */
.panel {
  background: rgba(255, 253, 248, .97);
  border: 1.5px solid rgba(81, 59, 81, .2);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
}
.panel-pad { padding: 18px; }
.panel-title { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 12px; }
.panel-title h3 { font-size: 15px; }
.panel-title .icon { color: var(--pink-deep); }
.rule { height: 1px; background: rgba(81,59,81,.13); border: 0; margin: 14px 0; }
.divider-dots { height: 10px; background-image: radial-gradient(rgba(81,59,81,.22) 1px, transparent 1px); background-size: 8px 8px; margin: 12px 0; }
.meter {
  position: relative; height: 10px; border-radius: 99px; background: #f0dfe3;
  border: 1px solid rgba(81,59,81,.13); overflow: hidden;
}
.meter > i {
  display: block; height: 100%; width: 0;
  background: linear-gradient(90deg, #ffb1c4, #e96d93);
  border-radius: inherit;
  transition: width .45s cubic-bezier(.2,.8,.2,1);
}
.meter.mint > i { background: linear-gradient(90deg, #b2e7d8, #5ab4a0); }
.meter.butter > i { background: linear-gradient(90deg, #ffe28d, #ecb73c); }
.meter.violet > i { background: linear-gradient(90deg, #cfc2f5, #8f79d1); }
.affection-line { display: flex; align-items: center; gap: 9px; }
.affection-line .meter { flex: 1; }
.affection-line b { font-size: 11px; color: var(--pink-deep); min-width: 26px; text-align: right; }
.heart-row { display: inline-flex; gap: 2px; align-items: center; color: #e2c9d1; }
.heart-row .heart { display: inline-flex; }
.heart-row .heart.filled { color: #e5668c; }
.heart-row .heart .icon { fill: none; }
.heart-row .heart.filled .icon { fill: currentColor; }
.heart-row.five { gap: 1px; }
.stat-pill {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 9px; border-radius: 999px;
  background: #fff7ec; border: 1px solid rgba(81,59,81,.12);
  color: var(--ink-soft); font-size: 10px; font-weight: 800;
}
.stat-pill .icon { color: var(--pink-deep); width: 13px; height: 13px; }
.tag-row { display: flex; flex-wrap: wrap; gap: 6px; }
.tag {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 4px 8px; border-radius: 999px;
  background: #f9edf1; color: #8f4a61;
  font-size: 9.5px; font-weight: 800; letter-spacing: .03em;
}
.tag.mint { background: #eaf7f2; color: #477e71; }
.tag.butter { background: #fff3d2; color: #8f681e; }
.tag.violet { background: #f0ebfb; color: #6c559e; }

/* ---------- Forms ---------- */
.field { display: grid; gap: 5px; }
.field > label, .field-label { font-size: 10px; font-weight: 900; letter-spacing: .1em; text-transform: uppercase; color: var(--ink-soft); }
.input, .select {
  width: 100%; min-height: 42px; padding: 8px 12px;
  border: 1.5px solid rgba(81,59,81,.23); border-radius: 12px;
  background: #fffaf3; color: var(--ink); font-size: 14px;
  box-shadow: inset 0 2px 5px rgba(81,59,81,.05);
}
.input:focus, .select:focus { outline: none; border-color: var(--pink-deep); box-shadow: 0 0 0 3px rgba(229,107,146,.18); }
.switch-row { display: flex; gap: 8px; flex-wrap: wrap; }
.select-chip {
  border: 1.5px solid rgba(81,59,81,.18); background: #fffaf4; border-radius: 12px;
  min-height: 38px; padding: 7px 11px; font-size: 11px; font-weight: 800; color: var(--ink-soft);
  display: inline-flex; align-items: center; gap: 6px;
}
.select-chip.active { background: var(--pink); color: #fff; border-color: var(--line); box-shadow: 0 2px 0 #a93e62; }

/* ---------- Toasts ---------- */
.toast-root {
  position: fixed; z-index: 1000; right: max(18px, env(safe-area-inset-right)); bottom: max(20px, env(safe-area-inset-bottom));
  display: flex; flex-direction: column; gap: 9px; width: min(340px, calc(100vw - 32px));
  pointer-events: none;
}
.toast {
  display: flex; gap: 10px; align-items: flex-start;
  padding: 12px 14px; border-radius: 15px;
  background: rgba(255, 251, 243, .98);
  border: 1.5px solid rgba(81,59,81,.24);
  box-shadow: 0 5px 0 rgba(81,59,81,.1), 0 18px 35px rgba(83,43,65,.18);
  animation: toast-in .32s cubic-bezier(.2,.8,.2,1), toast-out .35s ease 3.45s forwards;
  font-size: 12px; line-height: 1.4;
}
.toast .toast-icon {
  width: 30px; height: 30px; border-radius: 10px; flex: 0 0 auto;
  display: flex; align-items: center; justify-content: center;
  background: #ffe4ec; color: var(--pink-deep);
}
.toast.mint .toast-icon { background: #e4f6f0; color: var(--mint-deep); }
.toast.butter .toast-icon { background: #fff0c8; color: #a77725; }
.toast.night .toast-icon { background: #e8e3f8; color: #6952a1; }
.toast b { display: block; font-size: 12px; margin-bottom: 1px; }
.toast span { color: var(--ink-soft); }
@keyframes toast-in { from { transform: translateY(15px) scale(.96); opacity: 0; } }
@keyframes toast-out { to { transform: translateY(-5px); opacity: 0; } }

/* ---------- Modal shell ---------- */
.overlay-root { position: relative; z-index: 900; }
.modal-wrap {
  position: fixed; inset: 0; z-index: 900;
  display: flex; align-items: center; justify-content: center;
  padding: 18px;
  background: rgba(47, 33, 54, .55);
  backdrop-filter: blur(7px) saturate(.9);
  animation: fade-in .2s ease;
}
@keyframes fade-in { from { opacity: 0; } }
.modal {
  position: relative;
  width: min(620px, 100%);
  max-height: min(88dvh, 820px);
  overflow: auto;
  overscroll-behavior: contain;
  background: var(--paper);
  border: 2px solid var(--line);
  border-radius: 26px;
  box-shadow: 0 8px 0 rgba(66, 43, 62, .2), 0 32px 70px rgba(41, 20, 37, .34);
  animation: modal-in .28s cubic-bezier(.2,.9,.25,1.05);
  scrollbar-width: thin;
}
@keyframes modal-in { from { transform: translateY(18px) scale(.965); opacity: 0; } }
.modal.wide { width: min(960px, 100%); }
.modal.slim { width: min(460px, 100%); }
.modal-top {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 14px;
  padding: 20px 22px 14px;
}
.modal-top h2 { font-size: 24px; line-height: 1.05; }
.modal-top p { font-size: 12px; color: var(--ink-soft); margin-top: 5px; line-height: 1.4; }
.modal-close {
  flex: 0 0 auto; width: 34px; height: 34px; border-radius: 50%;
  border: 1.5px solid rgba(81,59,81,.18); background: #fff7ee; display: flex;
  align-items: center; justify-content: center; color: var(--ink-soft);
}
.modal-close:hover { color: var(--pink-deep); background: #ffeaf0; }
.modal-body { padding: 0 22px 22px; }
.modal-footer {
  display: flex; gap: 9px; flex-wrap: wrap; justify-content: flex-end;
  padding: 14px 22px max(18px, env(safe-area-inset-bottom));
  border-top: 1px solid rgba(81,59,81,.1);
  background: #fffbf4;
  position: sticky; bottom: 0;
}
.modal .ribbon {
  height: 7px; border-radius: 26px 26px 0 0;
  background: repeating-linear-gradient(90deg, var(--pink) 0 24px, var(--butter) 24px 48px, var(--mint) 48px 72px, var(--violet) 72px 96px);
}

/* ---------- Confetti ---------- */
.confetti-root { position: fixed; inset: 0; z-index: 1100; pointer-events: none; overflow: hidden; }
.confetti-piece {
  position: absolute; width: 9px; height: 14px; border-radius: 2px;
  top: -20px; animation: confetti-fall var(--dur, 2.5s) linear forwards;
  transform: rotate(var(--rot, 0deg));
}
@keyframes confetti-fall {
  0% { transform: translate3d(0, -5vh, 0) rotate(0turn); opacity: 1; }
  100% { transform: translate3d(var(--drift, 20px), 108vh, 0) rotate(2.2turn); opacity: .45; }
}

/* ---------- Empty and loading ---------- */
.empty-state {
  display: grid; justify-items: center; text-align: center; gap: 8px;
  padding: 36px 20px; color: var(--ink-soft);
}
.empty-state .empty-icon {
  width: 60px; height: 60px; border-radius: 50%; background: #fff1f4; color: var(--pink-deep);
  display: flex; align-items: center; justify-content: center; border: 1.5px dashed rgba(81,59,81,.28);
}
.empty-state h3 { color: var(--ink); font-size: 17px; }
.empty-state p { font-size: 12px; max-width: 320px; line-height: 1.5; }

/* ---------- Custom scrollbars ---------- */
* { scrollbar-width: thin; scrollbar-color: rgba(156,104,130,.42) transparent; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(156,104,130,.38); border: 3px solid transparent; background-clip: padding-box; border-radius: 99px; }
::-webkit-scrollbar-thumb:hover { background: rgba(156,104,130,.6); border: 3px solid transparent; background-clip: padding-box; }

/* ---------- Utility ---------- */
.flex { display: flex; }
.gap-6 { gap: 6px; } .gap-8 { gap: 8px; } .gap-10 { gap: 10px; } .gap-12 { gap: 12px; }
.items-center { align-items: center; } .justify-between { justify-content: space-between; }
.wrap { flex-wrap: wrap; }
.grow { flex: 1; }
.mt-4 { margin-top: 4px; } .mt-8 { margin-top: 8px; } .mt-12 { margin-top: 12px; } .mt-16 { margin-top: 16px; }
.mb-8 { margin-bottom: 8px; } .mb-12 { margin-bottom: 12px; }
.text-right { text-align: right; }
.nowrap { white-space: nowrap; }

/* Maple Hollow title screen — sunset town, candy logo, hero cast. */
.splash {
  position: relative;
  min-height: 100dvh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  isolation: isolate;
  background:
    radial-gradient(circle at 78% 18%, rgba(255, 250, 206, .9) 0 4%, transparent 17%),
    linear-gradient(180deg, #b9dbea 0%, #d7e6d8 22%, #ffd5ab 52%, #f6adad 72%, #dc8da2 100%);
}
.splash::before {
  content: "";
  position: absolute; inset: 0; z-index: -2;
  background:
    radial-gradient(circle at 20% 13%, rgba(255,255,255,.8) 0 1px, transparent 2px),
    radial-gradient(circle at 62% 8%, rgba(255,255,255,.55) 0 1px, transparent 2px),
    radial-gradient(circle at 84% 28%, rgba(255,255,255,.5) 0 1px, transparent 2px);
  background-size: 160px 140px, 210px 180px, 260px 230px;
  opacity: .7;
}
.splash::after {
  content: "";
  position: absolute; z-index: -1; left: -5%; right: -5%; bottom: -8%;
  height: 44%;
  background:
    radial-gradient(ellipse at 20% 100%, #7ca37e 0 38%, transparent 39%),
    radial-gradient(ellipse at 76% 100%, #94b584 0 45%, transparent 46%),
    radial-gradient(ellipse at 50% 100%, #6b956f 0 52%, transparent 53%);
  opacity: .8;
}
.splash-sky { position: absolute; inset: 0; z-index: -1; overflow: hidden; pointer-events: none; }
.splash-sun {
  position: absolute; right: 12%; top: 8%;
  width: clamp(180px, 23vw, 330px); aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle at 44% 42%, #fffbe1 0 28%, #ffe89f 42%, #ffd182 70%, rgba(255, 194, 127, 0) 71%);
  box-shadow: 0 0 0 30px rgba(255, 241, 182, .12), 0 0 0 70px rgba(255, 237, 173, .08);
  animation: sun-pulse 7s ease-in-out infinite;
}
@keyframes sun-pulse { 50% { transform: scale(1.035); filter: brightness(1.04); } }
.cloud {
  position: absolute; width: 190px; height: 54px; border-radius: 99px;
  background: rgba(255, 248, 240, .74);
  filter: blur(1px);
  animation: cloud-drift 40s linear infinite;
}
.cloud::before, .cloud::after {
  content: ""; position: absolute; bottom: 12px; border-radius: 50%; background: inherit;
}
.cloud::before { width: 74px; height: 74px; left: 28px; }
.cloud::after { width: 92px; height: 92px; right: 26px; bottom: 7px; }
.cloud-a { top: 17%; left: -4%; opacity: .75; animation-duration: 52s; }
.cloud-b { top: 33%; left: 38%; opacity: .48; transform: scale(.7); animation-duration: 66s; animation-delay: -20s; }
.cloud-c { top: 8%; left: 58%; opacity: .35; transform: scale(.55); animation-duration: 80s; animation-delay: -40s; }
@keyframes cloud-drift { from { translate: -20vw 0; } to { translate: 120vw 0; } }
.petal {
  position: absolute; width: 11px; height: 8px; border-radius: 80% 20% 60% 40%;
  background: #ffc1cd; opacity: .8;
  animation: petal-float 10s linear infinite;
}
.p1 { left: 7%; top: 25%; animation-delay: -2s; }
.p2 { left: 24%; top: 51%; transform: scale(.7); animation-delay: -7s; }
.p3 { left: 49%; top: 20%; transform: scale(.5); animation-delay: -4s; }
.p4 { left: 70%; top: 55%; animation-delay: -8s; }
.p5 { left: 86%; top: 33%; transform: scale(.6); animation-delay: -5s; }
.p6 { left: 37%; top: 76%; animation-delay: -9s; }
@keyframes petal-float {
  0% { translate: 0 -8vh; rotate: 0deg; opacity: 0; }
  15% { opacity: .85; }
  100% { translate: 8vw 82vh; rotate: 240deg; opacity: 0; }
}
.splash-grain {
  position: absolute; inset: 0; z-index: 3; pointer-events: none; opacity: .1;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.45'/%3E%3C/svg%3E");
  mix-blend-mode: multiply;
}

.splash-nav {
  position: relative; z-index: 4;
  display: flex; align-items: center; justify-content: space-between;
  gap: 18px; padding: 20px clamp(22px, 4vw, 62px);
}
.splash-brand { display: flex; align-items: center; gap: 11px; }
.brand-mark {
  width: 40px; height: 40px; border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  background: linear-gradient(150deg, #ffb1c2, #eb6c95);
  border: 2px solid var(--line);
  box-shadow: 0 3px 0 #9c3c5c, inset 0 2px 0 rgba(255,255,255,.5);
  color: white; transform: rotate(-7deg);
}
.brand-mark .brand-heart { font-size: 21px; line-height: 1; text-shadow: 0 1px 0 #9c3c5c; transform: rotate(7deg); }
.brand-mark.small { width: 33px; height: 33px; }
.brand-mark.small .brand-heart { font-size: 17px; }
.brand-word { font-family: var(--font-display); font-size: 13px; letter-spacing: .2em; color: #fffdf8; text-shadow: 0 1px 0 #9c5b6c, 0 2px 5px rgba(110,55,77,.2); }
.splash-meta { display: flex; gap: 8px; }
.meta-pill {
  display: inline-flex; align-items: center; min-height: 27px; padding: 5px 11px;
  border-radius: 999px; background: rgba(255,251,238,.68); border: 1.5px solid rgba(81,59,81,.35);
  font-size: 9px; font-weight: 900; letter-spacing: .12em; color: #6f4a60;
  backdrop-filter: blur(7px);
}
.meta-pill.hot { background: rgba(228, 96, 133, .88); border-color: #9e3e5e; color: #fff; text-shadow: 0 1px 0 rgba(103,31,57,.25); }

.splash-main {
  position: relative; z-index: 4;
  flex: 1;
  width: min(1340px, 100%);
  margin: 0 auto;
  padding: clamp(10px, 2vh, 32px) clamp(22px, 4vw, 64px) 30px;
  display: grid; grid-template-columns: minmax(340px, .9fr) minmax(380px, 1.15fr);
  align-items: center; gap: clamp(16px, 3vw, 60px);
}
.splash-copy { position: relative; z-index: 2; max-width: 570px; }
.splash-kicker {
  display: flex; align-items: center; gap: 8px;
  font-size: 10px; font-weight: 900; letter-spacing: .17em; color: #7d596a;
  text-transform: uppercase; margin-bottom: 9px;
}
.splash-kicker span { width: 24px; height: 1.5px; background: currentColor; opacity: .6; }
.logo {
  display: grid; line-height: .78;
  margin: 0 0 14px -4px;
  font-family: var(--font-display);
  font-size: clamp(67px, 8vw, 112px);
  font-weight: 900;
  letter-spacing: -.07em;
  color: #fff8ec;
  -webkit-text-stroke: clamp(2px, .26vw, 4px) #523444;
  paint-order: stroke fill;
  text-shadow: 0 5px 0 #b35d78, 0 10px 0 rgba(95,51,68,.22), 0 16px 24px rgba(91,41,59,.2);
  transform: rotate(-2.2deg);
}
.logo-maple { display: block; }
.logo-hollow {
  display: block; margin-left: clamp(32px, 4.5vw, 65px);
  color: #ffd9e0;
  -webkit-text-stroke-color: #67364f;
  text-shadow: 0 5px 0 #c45278, 0 10px 0 rgba(95,51,68,.22), 0 16px 24px rgba(91,41,59,.2);
}
.logo::after {
  content: "✦"; position: absolute; right: 1%; top: -2%;
  font-size: .35em; color: #fff3b0; -webkit-text-stroke: 1px #a56148;
  filter: drop-shadow(0 2px 0 #9d4c64); transform: rotate(8deg);
}
.splash-tagline {
  max-width: 500px; font-size: clamp(15px, 1.4vw, 19px); line-height: 1.45;
  font-weight: 700; color: #5b3e4c; margin-bottom: 9px;
}
.splash-copy-small { max-width: 490px; font-size: 12px; line-height: 1.55; color: #765768; margin-bottom: 21px; }
.splash-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 14px; }
.splash-note { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 9.5px; font-weight: 700; letter-spacing: .03em; color: #815f6c; }
.splash-note .dot { width: 3px; height: 3px; border-radius: 50%; background: currentColor; opacity: .55; }

.hero-stage {
  position: relative; min-height: min(63vh, 620px);
  display: flex; align-items: flex-end; justify-content: center;
}
.hero-burst {
  position: absolute; width: min(590px, 100%); aspect-ratio: 1; left: 50%; top: 48%;
  translate: -50% -50%; border-radius: 50%;
  background:
    repeating-conic-gradient(from 2deg, rgba(255,250,219,.86) 0 7deg, rgba(255,214,185,.45) 7deg 14deg),
    radial-gradient(circle, #fff8db 0 18%, #ffd9d6 47%, rgba(255,204,203,.1) 70%);
  border: 2px dashed rgba(128, 72, 89, .22);
  box-shadow: inset 0 0 0 14px rgba(255,252,232,.32), 0 22px 50px rgba(116, 47, 73, .15);
  animation: burst-turn 80s linear infinite;
  z-index: 0;
}
@keyframes burst-turn { to { rotate: 360deg; } }
.hero-burst::before {
  content: ""; position: absolute; inset: 21%; border-radius: 50%;
  background: radial-gradient(circle at 50% 50%, #fff9e8 0 35%, #ffe0cd 68%, rgba(255,208,204,.1) 69%);
}
.hero-cast {
  position: relative; z-index: 3; width: 100%; height: min(60vh, 580px);
  display: flex; align-items: flex-end; justify-content: center;
}
.hero-person {
  position: absolute; bottom: 2%;
  width: clamp(220px, 24vw, 315px); height: 84%;
  filter: drop-shadow(0 16px 18px rgba(94,49,68,.22));
  animation: hero-bob 5.5s ease-in-out infinite;
  transform-origin: 50% 100%;
}
.hero-person:nth-child(1) { left: 0; bottom: 1%; width: clamp(195px, 21vw, 280px); rotate: -5deg; animation-delay: -1.5s; }
.hero-person:nth-child(2) { left: 50%; translate: -50% 0; width: clamp(240px, 26vw, 345px); z-index: 4; bottom: 0; }
.hero-person:nth-child(3) { right: 0; bottom: 3%; width: clamp(195px, 21vw, 280px); rotate: 5deg; animation-delay: -3s; }
.hero-person:nth-child(4) { left: 35%; bottom: 22%; width: clamp(160px, 17vw, 225px); z-index: 5; rotate: 7deg; animation-delay: -4s; }
@keyframes hero-bob { 50% { transform: translateY(-9px); } }
.hero-person::after {
  content: ""; position: absolute; left: 13%; right: 13%; bottom: -1%; height: 20px;
  background: radial-gradient(ellipse, rgba(98, 47, 69, .23), transparent 67%);
  border-radius: 50%;
}
.hero-portrait {
  position: absolute; inset: 0 4% 0;
  display: flex; align-items: flex-end; justify-content: center;
  border-radius: 44% 44% 24% 24%;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(255,248,234,.26), rgba(255,211,215,.38));
  border: 2px solid rgba(95,52,70,.32);
  box-shadow: inset 0 0 0 7px rgba(255,251,240,.23);
}
.hero-portrait .avatar-svg { height: 116%; width: 118%; transform: translateY(4%); }
.hero-center .hero-portrait { border-radius: 46% 46% 22% 22%; background: linear-gradient(180deg, rgba(255,248,217,.2), rgba(255,183,194,.45)); }
.hero-person .name-tag {
  position: absolute; left: 50%; bottom: -13px; translate: -50%;
  z-index: 7; display: inline-flex; align-items: center; gap: 5px;
  padding: 6px 11px; border-radius: 999px; white-space: nowrap;
  background: #fffaf0; border: 1.5px solid var(--line);
  box-shadow: 0 3px 0 rgba(81,59,81,.15);
  font-family: var(--font-display); font-size: 11px;
}
.hero-person .name-tag small { font-family: var(--font-body); font-size: 8px; letter-spacing: .06em; color: var(--ink-soft); text-transform: uppercase; }
.hero-sticker {
  position: absolute; z-index: 8; display: flex; align-items: center; gap: 8px;
  padding: 9px 12px 9px 9px; border-radius: 15px;
  background: rgba(255, 251, 242, .92); border: 1.5px solid var(--line);
  box-shadow: 0 4px 0 rgba(81,59,81,.12), 0 13px 28px rgba(86,43,65,.15);
  backdrop-filter: blur(8px);
  animation: sticker-float 6s ease-in-out infinite;
}
.hero-sticker b { display: block; font-family: var(--font-display); font-size: 10px; line-height: 1.15; }
.hero-sticker small { display: block; font-size: 8px; color: var(--ink-soft); margin-top: 2px; }
.sticker-icon {
  width: 28px; height: 28px; border-radius: 9px;
  display: flex; align-items: center; justify-content: center;
  background: #ffe3ea; color: #b9476d; font-size: 15px;
}
.sticker-date { left: -2%; top: 17%; rotate: -4deg; animation-delay: -2s; }
.sticker-heart { right: -1%; top: 39%; rotate: 3.5deg; animation-delay: -4s; }
.sticker-heart .sticker-icon { background: #ffe6eb; color: #e35a84; }
.sticker-cal { right: 3%; bottom: 1%; rotate: -1.5deg; animation-delay: -1s; }
.sticker-cal .sticker-icon { background: #fff2c3; color: #a6741d; }
@keyframes sticker-float { 50% { translate: 0 -7px; } }
.hero-spark { position: absolute; z-index: 9; color: #fff8c7; text-shadow: 0 2px 0 #a25e59; font-size: 24px; animation: twinkle 3.5s ease-in-out infinite; }
.hero-spark.s1 { left: 7%; top: 7%; animation-delay: -1s; }
.hero-spark.s2 { right: 8%; top: 13%; font-size: 31px; animation-delay: -2.4s; }
.hero-spark.s3 { left: 12%; bottom: 30%; font-size: 17px; animation-delay: -.8s; }
.hero-spark.s4 { right: 22%; bottom: 18%; font-size: 19px; animation-delay: -3.2s; }

.splash-footer {
  position: relative; z-index: 5;
  display: flex; justify-content: space-between; align-items: center; gap: 14px;
  padding: 12px clamp(22px, 4vw, 62px) max(14px, env(safe-area-inset-bottom));
  color: rgba(255, 251, 242, .85); font-size: 9px; font-weight: 800;
  letter-spacing: .08em; text-transform: uppercase;
  text-shadow: 0 1px 0 rgba(98, 43, 65, .35);
}
.splash-footer-left { display: flex; align-items: center; gap: 7px; }
.splash-footer .mini-heart { color: #ffc3d3; }

@media (max-width: 980px) {
  .splash-main { grid-template-columns: 1fr; padding-top: 2px; }
  .splash-copy { max-width: 620px; margin: 0 auto; text-align: center; justify-items: center; }
  .splash-kicker, .splash-actions { justify-content: center; }
  .logo { margin-left: 0; }
  .logo-hollow { margin-left: 0; }
  .splash-tagline, .splash-copy-small { margin-left: auto; margin-right: auto; }
  .splash-note { justify-content: center; }
  .hero-stage { min-height: 430px; margin-top: -10px; }
  .hero-cast { height: 440px; }
  .hero-person { width: 240px; }
  .hero-person:nth-child(1), .hero-person:nth-child(3) { width: 205px; }
  .hero-person:nth-child(2) { width: 255px; }
  .hero-person:nth-child(4) { width: 170px; }
  .sticker-date { left: 3%; top: 10%; }
  .sticker-heart { right: 2%; top: 34%; }
  .sticker-cal { bottom: 0; }
}
@media (max-width: 640px) {
  .splash-nav { padding: 14px 16px; }
  .splash-brand .brand-word { font-size: 11px; }
  .splash-meta .meta-pill:first-child { display: none; }
  .splash-main { padding: 0 16px 15px; gap: 0; }
  .logo { font-size: clamp(57px, 16vw, 80px); }
  .splash-tagline { font-size: 14px; }
  .splash-copy-small { font-size: 11px; }
  .splash-actions { gap: 9px; }
  .btn-hero { min-width: 132px; min-height: 48px; }
  .hero-stage { min-height: 370px; margin-top: -2px; }
  .hero-cast { height: 370px; }
  .hero-person:nth-child(1), .hero-person:nth-child(3) { width: 165px; bottom: 4%; }
  .hero-person:nth-child(2) { width: 205px; }
  .hero-person:nth-child(4) { width: 140px; bottom: 22%; left: 28%; }
  .hero-person .name-tag { font-size: 9px; padding: 5px 8px; }
  .hero-person .name-tag small { display: none; }
  .sticker-date { display: none; }
  .sticker-heart { right: -4px; top: 32%; transform: scale(.82); }
  .sticker-cal { right: -4px; bottom: 0; transform: scale(.8); transform-origin: right bottom; }
  .splash-footer { justify-content: center; font-size: 8px; }
  .splash-footer-right { display: none; }
}

/* App frame: topbar, navigation, scrolling stage, and the daily rail. */
.game {
  height: 100dvh;
  display: grid;
  grid-template-rows: 72px minmax(0, 1fr);
  background: #f7e8df;
  overflow: hidden;
  position: relative;
}
.game::before {
  content: "";
  position: fixed; inset: 0; pointer-events: none; z-index: 0;
  background:
    radial-gradient(circle at 9% 18%, rgba(255,255,255,.7) 0 1px, transparent 2px),
    radial-gradient(circle at 63% 7%, rgba(255,255,255,.45) 0 1px, transparent 2px);
  background-size: 150px 120px, 220px 170px;
  opacity: .5;
}
.topbar {
  position: relative; z-index: 20;
  display: grid; grid-template-columns: 230px minmax(0, 1fr) auto;
  align-items: center; gap: 14px;
  height: 72px;
  padding: 0 20px;
  background: rgba(255, 252, 245, .9);
  border-bottom: 1.5px solid rgba(81, 59, 81, .18);
  backdrop-filter: blur(14px) saturate(1.15);
  box-shadow: 0 4px 18px rgba(99, 56, 74, .06);
}
.top-brand {
  display: flex; align-items: center; gap: 9px;
  border: 0; background: none; padding: 0; text-align: left;
}
.top-brand:hover .top-brand-copy b { color: var(--pink-deep); }
.top-brand-copy { display: grid; line-height: 1.1; }
.top-brand-copy b { font-family: var(--font-display); font-size: 11px; letter-spacing: .16em; transition: color .16s; }
.top-brand-copy small { font-size: 8px; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-faint); margin-top: 3px; }
.hud {
  justify-self: center;
  display: flex; align-items: center; gap: 7px; flex-wrap: nowrap;
}
.hud-pill {
  display: flex; align-items: center; gap: 8px;
  min-height: 44px; padding: 5px 12px 5px 7px;
  border-radius: 15px; border: 1.5px solid rgba(81,59,81,.14);
  background: rgba(255,255,255,.68);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.8);
}
.hud-pill > span:not(.hud-icon):not(.energy-copy) { display: grid; line-height: 1.05; }
.hud-pill small { font-size: 7.5px; letter-spacing: .12em; color: var(--ink-faint); font-weight: 900; }
.hud-pill b { font-family: var(--font-display); font-size: 12.5px; white-space: nowrap; }
.hud-icon {
  width: 30px; height: 30px; border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  background: #ffe9ef; color: #b9476d; font-family: var(--font-display); font-size: 15px;
}
.money-pill .hud-icon { background: #fff1c8; color: #94661b; }
.date-pill .hud-icon { background: #e8f4f7; color: #407f93; }
.energy-pill .hud-icon { background: #e7f7ef; color: #3e8a73; }
.energy-pill { padding-right: 11px; }
.energy-copy { display: grid; gap: 3px; min-width: 62px; }
.energy-bar { width: 68px; height: 6px; background: #eadfe4; border-radius: 99px; overflow: hidden; }
.energy-bar i { display: block; height: 100%; background: linear-gradient(90deg, #9edfc9, #55aa8c); border-radius: 99px; transition: width .35s; }
.energy-pill.low .energy-bar i { background: linear-gradient(90deg, #ffb071, #e86a57); }
.energy-pill > b { color: var(--mint-deep); }
.energy-pill.low > b { color: #bb513c; }
.top-actions { display: flex; gap: 6px; align-items: center; }
.top-actions .icon-btn { width: 36px; height: 36px; }

.game-shell {
  position: relative; z-index: 1;
  display: grid;
  grid-template-columns: 232px minmax(0, 1fr) 292px;
  min-height: 0;
}
.sidebar {
  min-height: 0;
  display: flex; flex-direction: column;
  padding: 16px 13px;
  background: rgba(255, 250, 241, .84);
  border-right: 1.5px solid rgba(81,59,81,.13);
  overflow-y: auto;
}
.sidebar-me {
  margin-bottom: 14px;
}
.me-card {
  display: flex; align-items: center; gap: 9px; position: relative;
  padding: 8px 9px 8px 7px;
  background: linear-gradient(135deg, #fffdf8, #fff1eb);
  border: 1.5px solid rgba(81,59,81,.18);
  border-radius: 17px;
  box-shadow: 0 3px 0 rgba(81,59,81,.08);
}
.me-portrait {
  width: 49px; height: 49px; border-radius: 13px; overflow: hidden;
  background: linear-gradient(160deg, #ffd8df, #ffeed9);
  border: 1.5px solid rgba(81,59,81,.16); flex: 0 0 auto;
}
.me-portrait .avatar-svg { width: 100%; height: 100%; transform: scale(1.2) translateY(5%); }
.me-copy { min-width: 0; display: grid; line-height: 1.1; }
.me-copy small { font-size: 7.5px; font-weight: 900; letter-spacing: .11em; color: var(--ink-faint); }
.me-copy b { font-family: var(--font-display); font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin: 2px 0; }
.me-copy span { font-size: 8.5px; color: var(--ink-soft); white-space: nowrap; }
.me-edit {
  position: absolute; right: 6px; bottom: 6px; width: 22px; height: 22px;
  border-radius: 50%; border: 1px solid rgba(81,59,81,.15); background: #fff;
  display: flex; align-items: center; justify-content: center; color: var(--ink-soft);
}
.me-edit:hover { color: var(--pink-deep); }
.nav-list { display: flex; flex-direction: column; gap: 4px; }
.nav-item {
  position: relative; width: 100%;
  display: flex; align-items: center; gap: 9px;
  min-height: 46px; padding: 7px 9px;
  border: 1.5px solid transparent; border-radius: 13px;
  background: transparent; color: var(--ink-soft); text-align: left;
  transition: .16s ease;
}
.nav-item:hover { background: rgba(255,255,255,.7); color: var(--ink); }
.nav-item.active {
  background: #fff7ef; border-color: rgba(81,59,81,.2);
  color: var(--ink); box-shadow: 0 3px 0 rgba(81,59,81,.08);
}
.nav-item.active::before {
  content: ""; position: absolute; left: -14px; top: 12px; bottom: 12px;
  width: 4px; border-radius: 0 4px 4px 0; background: var(--pink-hot);
}
.nav-icon {
  width: 31px; height: 31px; border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  background: #f7ece8; color: #9c7182; flex: 0 0 auto;
  transition: .16s;
}
.nav-item.active .nav-icon { background: #ffe3eb; color: var(--pink-deep); }
.nav-item[data-screen="family"] .nav-icon { background: #e9f4ed; color: #5b8f69; }
.nav-item[data-screen="perks"] .nav-icon { background: #fff1ca; color: #9c7020; }
.nav-item[data-screen="mirror"] .nav-icon { background: #eee9fa; color: #7662a9; }
.nav-copy { display: grid; flex: 1; min-width: 0; line-height: 1.15; }
.nav-copy b { font-size: 11.5px; color: inherit; }
.nav-copy small { font-size: 8px; color: var(--ink-faint); margin-top: 2px; }
.nav-badge {
  min-width: 20px; height: 20px; border-radius: 999px; padding: 0 6px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--pink-hot); color: #fff; font-size: 9px; font-style: normal; font-weight: 900;
}
.nav-badge.soft { background: #f5dfe6; color: #a24964; }
.sidebar-event { margin-top: auto; padding-top: 16px; }
.event-mini {
  position: relative; overflow: hidden;
  padding: 12px 13px; border-radius: 17px;
  background: linear-gradient(145deg, #ffe6e9, #ffd7dd);
  border: 1.5px solid rgba(81,59,81,.19);
  box-shadow: 0 3px 0 rgba(81,59,81,.07);
}
.event-mini::after {
  content: "✦"; position: absolute; right: 9px; top: 5px; font-size: 28px; color: rgba(255,255,255,.7);
}
.event-mini .event-top { display: flex; gap: 7px; align-items: center; margin-bottom: 6px; }
.event-mini .event-icon { width: 27px; height: 27px; border-radius: 9px; display: flex; align-items: center; justify-content: center; background: #fff7e4; color: #c06935; }
.event-mini b { font-family: var(--font-display); font-size: 11px; line-height: 1.15; display: block; }
.event-mini small { font-size: 8px; color: #8b5969; display: block; margin-top: 2px; }
.event-mini p { position: relative; z-index: 2; font-size: 9.5px; line-height: 1.4; color: #805363; margin-top: 5px; }
.sidebar-footer { display: flex; align-items: center; justify-content: space-between; padding: 13px 3px 0; }
.main-scroll {
  min-height: 0; overflow-y: auto; overflow-x: hidden;
  background:
    radial-gradient(circle at 12% 9%, rgba(255,255,255,.6) 0 1px, transparent 2px),
    radial-gradient(circle at 78% 26%, rgba(255,255,255,.35) 0 1px, transparent 2px),
    linear-gradient(180deg, #fdf2e7 0%, #f9e9e3 52%, #f6e4df 100%);
  background-size: 180px 150px, 240px 210px, auto;
  scroll-behavior: smooth;
}
.view { padding: 23px 24px 36px; max-width: 1140px; margin: 0 auto; min-height: 100%; }
.right-rail {
  min-height: 0; overflow-y: auto;
  padding: 17px 14px 28px;
  background: rgba(255, 251, 244, .8);
  border-left: 1.5px solid rgba(81,59,81,.13);
}
.rail-card {
  background: #fffdf8; border: 1.5px solid rgba(81,59,81,.15);
  border-radius: 17px; padding: 13px;
  box-shadow: 0 3px 0 rgba(81,59,81,.06);
  margin-bottom: 11px;
}
.rail-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 9px; }
.rail-head h3 { font-size: 11px; letter-spacing: .04em; display: flex; align-items: center; gap: 6px; }
.rail-head .icon { color: var(--pink-deep); width: 15px; height: 15px; }
.rail-head small { font-size: 8px; color: var(--ink-faint); font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.rail-card p { font-size: 9.5px; line-height: 1.45; color: var(--ink-soft); }
.rail-cal {
  text-align: center;
  background:
    linear-gradient(180deg, #ffd9e1 0 28%, #fffdf8 28%);
  overflow: hidden; padding: 0;
}
.rail-cal .cal-top { padding: 9px 12px; display: flex; justify-content: space-between; align-items: center; font-size: 8px; font-weight: 900; letter-spacing: .1em; text-transform: uppercase; color: #8b435e; }
.rail-cal .cal-body { padding: 12px 13px 14px; display: flex; align-items: center; gap: 11px; text-align: left; }
.rail-cal .cal-day { font-family: var(--font-display); font-size: 44px; line-height: .85; color: var(--ink); }
.rail-cal .cal-info b { display: block; font-size: 10.5px; }
.rail-cal .cal-info small { display: block; font-size: 8.5px; color: var(--ink-soft); margin-top: 2px; line-height: 1.45; }
.rail-cal .cal-week { display: grid; grid-template-columns: repeat(7, 1fr); gap: 2px; padding: 0 9px 11px; }
.rail-cal .cal-week span { display: grid; justify-items: center; gap: 3px; font-size: 7px; color: var(--ink-faint); font-weight: 800; }
.rail-cal .cal-week i { width: 22px; height: 22px; display: flex; align-items: center; justify-content: center; font-size: 8px; font-style: normal; border-radius: 50%; color: var(--ink-soft); }
.rail-cal .cal-week i.today { background: var(--pink-hot); color: #fff; font-weight: 900; }
.rail-cal .cal-week i.event { box-shadow: inset 0 0 0 1.5px #e5b2c1; }
.household-mini { display: flex; gap: 5px; margin-bottom: 8px; }
.household-mini .mini-avatar { flex: 1; aspect-ratio: .82; border-radius: 10px; overflow: hidden; background: #ffeadf; border: 1px solid rgba(81,59,81,.1); }
.household-mini .mini-avatar .avatar-svg { width: 120%; height: 120%; transform: translate(-8%, 2%); }
.household-mini .mini-more { width: 31px; flex: 0 0 auto; border-radius: 10px; display: flex; align-items: center; justify-content: center; background: #f5e8ea; color: var(--pink-deep); font-family: var(--font-display); font-size: 11px; }
.household-line { display: flex; justify-content: space-between; font-size: 9px; color: var(--ink-soft); padding: 3px 0; }
.household-line b { color: var(--ink); font-size: 9.5px; }
.whisper { display: flex; gap: 7px; padding: 7px 0; border-bottom: 1px dashed rgba(81,59,81,.11); font-size: 9px; line-height: 1.4; color: var(--ink-soft); }
.whisper:last-child { border: 0; padding-bottom: 0; }
.whisper .w-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--pink); margin-top: 5px; flex: 0 0 auto; }
.whisper b { color: var(--ink); font-size: 9.5px; }
.rail-adventure {
  background: linear-gradient(150deg, #e6f4ee, #d4edf0);
  border-color: #b9dcd5;
}
.rail-adventure .rail-head h3 { color: #377a6e; }
.rail-adventure .btn { margin-top: 4px; }

.mobile-nav { display: none; }

/* Phase tinting */
.game[data-phase="evening"] .main-scroll {
  background:
    radial-gradient(circle at 80% 10%, rgba(255,201,160,.3), transparent 32%),
    linear-gradient(180deg, #fff0df 0%, #f6e1de 52%, #eedce4 100%);
}
.game[data-phase="night"] .main-scroll {
  background:
    radial-gradient(circle at 84% 6%, rgba(255,238,169,.18), transparent 26%),
    linear-gradient(180deg, #3d3b5d 0%, #4a4364 45%, #5f4c66 100%);
}
.game[data-phase="night"] .topbar { background: rgba(52,45,71,.92); border-bottom-color: rgba(255,255,255,.1); }
.game[data-phase="night"] .top-brand-copy b,
.game[data-phase="night"] .top-brand-copy small { color: #f9edf2; }
.game[data-phase="night"] .hud-pill { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.12); color: #fff7ef; }
.game[data-phase="night"] .hud-pill small { color: #c9bfd8; }
.game[data-phase="night"] .sidebar { background: rgba(50,45,69,.88); border-color: rgba(255,255,255,.08); }
.game[data-phase="night"] .nav-item { color: #cfc8db; }
.game[data-phase="night"] .nav-item.active { background: rgba(255,255,255,.12); color: #fff; border-color: rgba(255,255,255,.15); }
.game[data-phase="night"] .nav-copy small { color: #a99fb8; }
.game[data-phase="night"] .me-card { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.14); color: #fff; }
.game[data-phase="night"] .me-copy small { color: #b7acc7; }
.game[data-phase="night"] .me-copy span { color: #c3b9d1; }
.game[data-phase="night"] .sidebar-footer .text-btn { color: #bdb3ca; }
.game[data-phase="night"] .right-rail { background: rgba(50,45,69,.86); border-color: rgba(255,255,255,.08); }
.game[data-phase="night"] .rail-card { background: rgba(255,255,255,.09); border-color: rgba(255,255,255,.1); color: #f8eff3; }
.game[data-phase="night"] .rail-card p,
.game[data-phase="night"] .rail-head small,
.game[data-phase="night"] .household-line,
.game[data-phase="night"] .whisper { color: #bfb5cc; }
.game[data-phase="night"] .household-line b,
.game[data-phase="night"] .whisper b,
.game[data-phase="night"] .rail-card b { color: #fff8fa; }
.game[data-phase="night"] .rail-cal { background: linear-gradient(180deg, #6b4a68 0 28%, rgba(255,255,255,.08) 28%); }
.game[data-phase="night"] .rail-cal .cal-day { color: #fff4f5; }
.game[data-phase="night"] .rail-cal .cal-info small { color: #c6bbd0; }
.game[data-phase="night"] .event-mini { background: linear-gradient(145deg, #5b4468, #493a5f); border-color: rgba(255,255,255,.1); }
.game[data-phase="night"] .event-mini b { color: #fff; }
.game[data-phase="night"] .event-mini small,
.game[data-phase="night"] .event-mini p { color: #c9bed7; }

/* Tablet: collapse the right rail first. */
@media (max-width: 1180px) {
  .game-shell { grid-template-columns: 218px minmax(0, 1fr); }
  .right-rail { display: none; }
  .topbar { grid-template-columns: 210px minmax(0, 1fr) auto; }
}
@media (max-width: 860px) {
  .game { grid-template-rows: 62px minmax(0, 1fr) calc(63px + var(--safe-bottom)); }
  .topbar { grid-template-columns: auto minmax(0, 1fr) auto; height: 62px; padding: 0 12px; gap: 10px; }
  .top-brand-copy { display: none; }
  .top-brand .brand-mark.small { width: 35px; height: 35px; }
  .hud { gap: 4px; justify-self: center; }
  .hud-pill { min-height: 37px; padding: 3px 7px; border-radius: 11px; gap: 5px; }
  .hud-icon { width: 25px; height: 25px; border-radius: 8px; font-size: 12px; }
  .hud-pill small { font-size: 6px; }
  .hud-pill b { font-size: 10px; }
  .date-pill { display: none; }
  .energy-copy .energy-bar { width: 48px; }
  .energy-pill { padding-right: 7px; }
  .top-actions .icon-btn:nth-child(3) { display: none; }
  .game-shell { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .view { padding: 15px 14px 22px; }
  .mobile-nav {
    display: grid; grid-template-columns: repeat(5, 1fr);
    height: calc(63px + var(--safe-bottom));
    padding: 5px 5px var(--safe-bottom);
    background: rgba(255, 251, 244, .97);
    border-top: 1.5px solid rgba(81,59,81,.18);
    box-shadow: 0 -8px 24px rgba(95,50,69,.08);
    z-index: 30;
    backdrop-filter: blur(15px);
  }
  .mobile-nav .nav-item {
    display: grid; justify-items: center; align-content: center; gap: 2px;
    min-height: 50px; padding: 4px 2px; border: 0; border-radius: 11px;
    background: transparent;
  }
  .mobile-nav .nav-item.active { background: #fff0eb; box-shadow: none; }
  .mobile-nav .nav-item.active::before { display: none; }
  .mobile-nav .nav-icon { width: 24px; height: 24px; background: transparent; }
  .mobile-nav .nav-item.active .nav-icon { background: transparent; }
  .mobile-nav .nav-copy { display: block; flex: none; }
  .mobile-nav .nav-copy b { font-size: 8px; }
  .mobile-nav .nav-copy small, .mobile-nav .nav-badge { display: none; }
  .game[data-phase="night"] .mobile-nav { background: rgba(48,42,65,.97); border-color: rgba(255,255,255,.1); }
  .game[data-phase="night"] .mobile-nav .nav-item { color: #c9c0d4; }
  .game[data-phase="night"] .mobile-nav .nav-item.active { background: rgba(255,255,255,.1); color: #fff; }
}
@media (max-width: 430px) {
  .hud-pill { padding: 3px 5px; }
  .money-pill .hud-icon { width: 23px; height: 23px; }
  .energy-pill .hud-icon { display: none; }
  .energy-copy { min-width: 41px; }
  .energy-copy .energy-bar { width: 35px; }
  .top-actions { gap: 2px; }
  .top-actions .icon-btn { width: 32px; height: 32px; }
}

/* Town map and location cards. */
.view-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 16px;
  margin-bottom: 17px;
}
.view-head .heading-copy { min-width: 0; }
.view-head .eyebrow { margin-bottom: 5px; }
.view-head h1 { font-size: clamp(28px, 3.1vw, 40px); line-height: .98; letter-spacing: -.045em; }
.view-head h1 .script { color: var(--pink-deep); font-style: italic; }
.view-head p.sub { margin-top: 6px; font-size: 11px; line-height: 1.5; color: var(--ink-soft); max-width: 560px; }
.head-actions { display: flex; align-items: center; gap: 7px; flex-wrap: wrap; justify-content: flex-end; }

.map-layout { display: grid; grid-template-columns: minmax(0, 1fr) 250px; gap: 14px; align-items: start; }
.map-frame {
  position: relative; overflow: hidden;
  border: 2px solid var(--line); border-radius: 24px;
  background: #e8d6b4;
  box-shadow: 0 6px 0 rgba(81,59,81,.14), 0 20px 40px rgba(81,59,81,.1);
}
.map-topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  min-height: 43px; padding: 8px 12px;
  background: rgba(255, 251, 241, .94);
  border-bottom: 1.5px solid rgba(81,59,81,.16);
}
.map-topbar .map-title { display: flex; align-items: center; gap: 7px; font-family: var(--font-display); font-size: 12px; }
.map-topbar .map-title .icon { color: var(--pink-deep); }
.map-topbar .map-hint { font-size: 8px; color: var(--ink-faint); letter-spacing: .07em; text-transform: uppercase; display: flex; align-items: center; gap: 4px; }
.map-scroll {
  overflow: auto; overscroll-behavior: contain; touch-action: pan-x pan-y;
  max-height: min(59vh, 590px);
  background: #efdfc2;
  scrollbar-width: thin;
}
.map-canvas {
  position: relative;
  width: 100%; min-width: 660px;
  aspect-ratio: 1.5;
  overflow: hidden;
  background: #cddca9;
  isolation: isolate;
}
.map-art { position: absolute; inset: 0; width: 100%; height: 100%; }
.map-canvas::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 56%, rgba(92,64,51,.18) 100%);
  mix-blend-mode: multiply;
}
.map-node {
  position: absolute; z-index: 5; translate: -50% -50%;
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  border: 0; background: none; padding: 0;
  filter: drop-shadow(0 4px 5px rgba(75,50,45,.16));
  transition: transform .18s cubic-bezier(.2,.8,.2,1), filter .18s;
}
.map-node:hover, .map-node.active { transform: scale(1.06); filter: drop-shadow(0 6px 8px rgba(75,50,45,.24)); }
.map-node:focus-visible { outline-offset: 6px; border-radius: 18px; }
.node-pin {
  position: relative; width: 39px; height: 39px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: var(--loc-bg, #f4b6c3); color: var(--loc-ink, #74354f);
  border: 2px solid var(--line);
  box-shadow: 0 3px 0 rgba(81,59,81,.2), inset 0 2px 0 rgba(255,255,255,.45);
}
.node-pin .icon { width: 20px; height: 20px; }
.node-pin::after {
  content: ""; position: absolute; width: 7px; height: 7px; border-radius: 50%;
  background: var(--loc-ink, #74354f); opacity: .55; bottom: -5px;
}
.node-label {
  display: inline-flex; align-items: center; gap: 4px;
  min-height: 20px; padding: 2px 6px;
  border-radius: 999px; background: rgba(255,253,246,.9);
  border: 1.2px solid rgba(81,59,81,.22);
  font-size: 7.5px; font-weight: 900; letter-spacing: .03em; color: #503b47;
  white-space: nowrap;
  box-shadow: 0 2px 0 rgba(81,59,81,.08);
}
.node-label .count {
  min-width: 14px; height: 14px; border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--loc-bg, #f4b6c3); color: var(--loc-ink, #74354f);
  font-size: 7px; border: 1px solid rgba(81,59,81,.2);
}
.map-node.active .node-pin {
  box-shadow: 0 0 0 4px rgba(255,249,236,.8), 0 0 0 7px var(--loc-bg, #f4b6c3), 0 4px 0 rgba(81,59,81,.2);
}
.map-node.active .node-label { background: var(--loc-bg, #f4b6c3); color: var(--loc-ink, #74354f); border-color: var(--line); }
.you-marker {
  position: absolute; z-index: 9; translate: -50% -100%;
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  pointer-events: none; transition: left .4s ease, top .4s ease;
}
.you-marker .you-bubble {
  padding: 2px 7px; border-radius: 99px;
  background: #fff9ed; border: 1.3px solid var(--line);
  font-size: 7px; font-weight: 900; letter-spacing: .05em; color: #664353;
  box-shadow: 0 2px 0 rgba(81,59,81,.12);
}
.you-marker .you-head {
  width: 28px; height: 28px; border-radius: 50%; overflow: hidden;
  background: #ffe4d4; border: 2px solid #fffaf0;
  box-shadow: 0 0 0 1.5px var(--line), 0 3px 5px rgba(81,59,81,.2);
}
.you-marker .you-head .avatar-svg { width: 110%; height: 110%; transform: translate(-4%, 4%); }
.map-compass {
  position: absolute; right: 12px; top: 13px; z-index: 4;
  width: 43px; height: 43px; border-radius: 50%;
  background: rgba(255,250,237,.84); border: 1.5px solid rgba(81,59,81,.23);
  display: grid; place-items: center; color: #8c5e52;
  font-family: var(--font-display); font-size: 8px; letter-spacing: .08em;
  box-shadow: 0 2px 0 rgba(81,59,81,.1);
}
.map-compass::before {
  content: ""; position: absolute; width: 2px; height: 16px;
  background: linear-gradient(#c95e71 0 50%, #72584b 50%);
  top: 6px; border-radius: 2px;
}
.map-compass span { margin-top: 22px; }
.map-weather {
  position: absolute; left: 11px; bottom: 11px; z-index: 5;
  display: flex; align-items: center; gap: 6px; padding: 5px 8px;
  border-radius: 10px; background: rgba(255,250,238,.88);
  border: 1px solid rgba(81,59,81,.16); font-size: 8px; font-weight: 800; color: #74604d;
  box-shadow: 0 2px 0 rgba(81,59,81,.09);
}
.map-weather .icon { color: #b57546; width: 14px; height: 14px; }
.map-legend {
  position: absolute; right: 11px; bottom: 11px; z-index: 5;
  display: flex; align-items: center; gap: 4px;
  padding: 5px 8px; border-radius: 10px; background: rgba(255,250,238,.82);
  border: 1px solid rgba(81,59,81,.15); font-size: 7.5px; color: #7d685d;
}
.map-legend i { width: 5px; height: 5px; border-radius: 50%; background: #d95e82; }
.map-scroll-foot {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding: 7px 11px; background: rgba(255, 250, 241, .94);
  border-top: 1.5px solid rgba(81,59,81,.13);
  font-size: 8px; color: var(--ink-faint);
}
.map-scroll-foot span { display: flex; align-items: center; gap: 4px; }
.map-scroll-foot .map-pan-note { color: #a57679; font-weight: 800; }

.map-side { display: flex; flex-direction: column; gap: 11px; }
.local-card {
  background: var(--paper); border: 1.5px solid rgba(81,59,81,.18);
  border-radius: 19px; padding: 13px;
  box-shadow: 0 4px 0 rgba(81,59,81,.07);
}
.local-card .loc-badge {
  width: 36px; height: 36px; border-radius: 12px; display: flex; align-items: center; justify-content: center;
  background: var(--loc-bg, #f4b6c3); color: var(--loc-ink, #74354f);
  border: 1.5px solid var(--line); margin-bottom: 8px;
}
.local-card h3 { font-size: 15px; line-height: 1.1; }
.local-card p { font-size: 9.5px; line-height: 1.45; color: var(--ink-soft); margin-top: 4px; }
.local-actions { display: flex; gap: 5px; flex-wrap: wrap; margin-top: 10px; }
.local-people { display: grid; gap: 6px; margin-top: 11px; padding-top: 10px; border-top: 1px dashed rgba(81,59,81,.14); }
.local-person {
  display: flex; align-items: center; gap: 7px; width: 100%;
  border: 1px solid rgba(81,59,81,.11); background: #fffaf4;
  border-radius: 11px; padding: 4px 6px 4px 4px; text-align: left;
}
.local-person:hover { background: #fff; border-color: rgba(81,59,81,.24); }
.local-person .lp-face { width: 31px; height: 31px; border-radius: 9px; overflow: hidden; background: #ffe8da; flex: 0 0 auto; }
.local-person .lp-face .avatar-svg { width: 115%; height: 115%; transform: translate(-7%, 3%); }
.local-person .lp-copy { display: grid; min-width: 0; flex: 1; line-height: 1.1; }
.local-person .lp-copy b { font-size: 9.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.local-person .lp-copy small { font-size: 7.5px; color: var(--ink-faint); margin-top: 2px; }
.local-person .lp-heart { color: var(--pink-deep); font-size: 9px; font-weight: 900; }
.map-tip {
  padding: 12px; border-radius: 17px;
  background: linear-gradient(145deg, #fff4cf, #ffe9c4);
  border: 1.5px solid rgba(169,121,47,.26);
}
.map-tip b { display: flex; align-items: center; gap: 5px; font-size: 9.5px; color: #8b611f; }
.map-tip p { font-size: 9px; line-height: 1.5; color: #826939; margin-top: 4px; }
.map-tip .icon { width: 14px; height: 14px; }

/* Map palette by phase */
.game[data-phase="night"] .map-frame { box-shadow: 0 6px 0 rgba(20,16,36,.22), 0 22px 45px rgba(20,16,36,.24); }
.game[data-phase="night"] .map-topbar,
.game[data-phase="night"] .map-scroll-foot { background: rgba(53,49,72,.95); color: #e9e3ee; border-color: rgba(255,255,255,.09); }
.game[data-phase="night"] .map-topbar .map-title { color: #f8edf3; }
.game[data-phase="night"] .map-topbar .map-hint { color: #b4a9c3; }
.game[data-phase="night"] .node-label { background: rgba(51,47,71,.88); color: #f4e9ef; border-color: rgba(255,255,255,.18); }
.game[data-phase="night"] .local-card { background: rgba(255,255,255,.09); border-color: rgba(255,255,255,.1); color: #fff; }
.game[data-phase="night"] .local-card p { color: #c0b5cc; }
.game[data-phase="night"] .local-person { background: rgba(255,255,255,.06); border-color: rgba(255,255,255,.09); color: #f6edf2; }
.game[data-phase="night"] .local-person .lp-copy small { color: #b4a9c2; }
.game[data-phase="night"] .map-tip { background: rgba(255,244,207,.09); border-color: rgba(255,239,184,.18); }
.game[data-phase="night"] .map-tip b { color: #ffe8a2; }
.game[data-phase="night"] .map-tip p { color: #c7baa5; }
.game[data-phase="night"] .you-marker .you-bubble { background: #3e3858; color: #fff; border-color: rgba(255,255,255,.25); }

@media (max-width: 1080px) {
  .map-layout { grid-template-columns: 1fr; }
  .map-side { display: grid; grid-template-columns: 1.2fr .8fr; align-items: start; }
  .map-side .map-tip { grid-column: 2; }
  .local-card { grid-row: span 2; }
}
@media (max-width: 700px) {
  .view-head { align-items: flex-start; flex-direction: column; gap: 9px; }
  .view-head h1 { font-size: 32px; }
  .head-actions { justify-content: flex-start; }
  .map-scroll { max-height: 46vh; }
  .map-canvas { min-width: 620px; }
  .map-side { grid-template-columns: 1fr; }
  .map-side .map-tip { grid-column: auto; }
  .local-card { grid-row: auto; }
}

/* Suitor cards, relationship scene, family album, perks, and the mirror. */

/* ---------- Shared section bits ---------- */
.section-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 21px 0 11px; }
.section-head h2 { font-size: 17px; display: flex; align-items: center; gap: 7px; }
.section-head h2 .icon { color: var(--pink-deep); }
.section-head p { font-size: 10px; color: var(--ink-soft); }
.filter-row { display: flex; gap: 5px; flex-wrap: wrap; align-items: center; }
.filter-chip {
  min-height: 31px; padding: 5px 11px; border-radius: 99px;
  border: 1.5px solid rgba(81,59,81,.16); background: rgba(255,253,246,.75);
  font-size: 9px; font-weight: 900; letter-spacing: .04em; color: var(--ink-soft);
}
.filter-chip:hover { background: #fff; }
.filter-chip.active { background: var(--ink); color: #fff; border-color: var(--ink); box-shadow: 0 2px 0 rgba(81,59,81,.18); }

/* ---------- Suitor roster ---------- */
.suitor-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.suitor-card {
  position: relative; overflow: hidden;
  background: var(--paper); border: 1.5px solid rgba(81,59,81,.19);
  border-radius: 20px; box-shadow: var(--shadow-card);
  transition: transform .18s ease, box-shadow .18s ease;
}
.suitor-card:hover { transform: translateY(-3px); box-shadow: 0 7px 0 rgba(86,53,73,.1), 0 20px 35px rgba(97,54,73,.12); }
.suitor-portrait {
  position: relative; height: 208px; overflow: hidden;
  background:
    radial-gradient(circle at 73% 20%, rgba(255,255,255,.65) 0 8%, transparent 9%),
    linear-gradient(150deg, var(--port-a, #ffd7df), var(--port-b, #ffeed4));
  border-bottom: 1.5px solid rgba(81,59,81,.13);
}
.suitor-portrait::before {
  content: ""; position: absolute; inset: 9% 7% 0;
  border-radius: 50% 50% 18% 18%;
  border: 1.5px dashed rgba(255,255,255,.55);
}
.suitor-portrait::after {
  content: ""; position: absolute; left: 12%; right: 12%; bottom: -14px; height: 15px;
  border-radius: 50%; background: rgba(81,59,81,.16); filter: blur(4px);
}
.suitor-portrait .avatar-svg {
  position: absolute; z-index: 2; width: 98%; height: 126%; left: 1%; bottom: -17%;
  filter: drop-shadow(0 7px 7px rgba(83,46,63,.13));
  transition: transform .35s ease;
}
.suitor-card:hover .avatar-svg { transform: translateY(-4px); }
.portrait-badges { position: absolute; z-index: 4; left: 8px; top: 8px; right: 8px; display: flex; justify-content: space-between; gap: 5px; }
.portrait-badges .chip { font-size: 7.5px; min-height: 21px; padding: 3px 7px; background: rgba(255,252,242,.9); }
.suitor-heart-badge {
  position: absolute; z-index: 4; right: 9px; bottom: 9px;
  display: flex; align-items: center; gap: 3px;
  padding: 4px 7px; border-radius: 999px;
  background: rgba(255,250,240,.9); border: 1px solid rgba(81,59,81,.15);
  font-size: 9px; font-weight: 900; color: var(--pink-deep);
}
.suitor-heart-badge .icon { width: 12px; height: 12px; fill: currentColor; }
.suitor-info { padding: 11px 12px 12px; }
.suitor-name-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 6px; }
.suitor-name-row h3 { font-size: 17px; line-height: 1; }
.suitor-name-row .age { font-size: 9px; color: var(--ink-faint); font-weight: 800; margin-top: 3px; }
.suitor-sub { font-size: 8.5px; color: var(--ink-soft); margin-top: 4px; line-height: 1.3; min-height: 22px; }
.suitor-info .affection-line { margin-top: 8px; }
.suitor-card-actions { display: flex; gap: 5px; margin-top: 9px; }
.suitor-card-actions .btn { flex: 1; }
.suitor-leaving {
  display: flex; align-items: center; gap: 4px;
  margin-top: 8px; padding: 5px 6px; border-radius: 8px;
  background: #fff0dc; color: #a26a24; font-size: 7.5px; font-weight: 800;
}
.suitor-leaving .icon { width: 11px; height: 11px; }
.relationship-ribbon {
  position: absolute; z-index: 3; left: 0; top: 14px;
  padding: 3px 8px 3px 6px; border-radius: 0 9px 9px 0;
  background: var(--pink-hot); color: #fff; font-size: 7px; font-weight: 900; letter-spacing: .06em;
  border: 1px solid #8f3653; border-left: 0;
}

/* ---------- Profile scene ---------- */
.profile-view { padding-bottom: 12px; }
.profile-breadcrumb { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
.profile-hero { display: grid; grid-template-columns: minmax(280px, .85fr) minmax(380px, 1.35fr); gap: 16px; align-items: stretch; }
.portrait-stage {
  position: relative; min-height: 420px; overflow: hidden;
  background:
    radial-gradient(circle at 50% 33%, rgba(255,255,255,.7) 0 24%, transparent 25%),
    repeating-conic-gradient(from 15deg at 50% 44%, rgba(255,255,255,.18) 0 12deg, transparent 12deg 24deg),
    linear-gradient(160deg, var(--stage-a, #ffd4df), var(--stage-b, #ffeacb));
  border: 2px solid var(--line); border-radius: 25px;
  box-shadow: 0 6px 0 rgba(81,59,81,.13), 0 20px 40px rgba(81,59,81,.1);
  display: flex; align-items: flex-end; justify-content: center;
}
.portrait-stage::before {
  content: ""; position: absolute; z-index: 0; left: 9%; right: 9%; top: 8%; bottom: 18%;
  border-radius: 46% 46% 22% 22%; border: 1.5px dashed rgba(255,255,255,.65);
}
.portrait-stage::after {
  content: ""; position: absolute; z-index: 0; left: 50%; top: 45%; translate: -50% -50%;
  width: 75%; aspect-ratio: 1; border-radius: 50%;
  background: radial-gradient(circle, rgba(255,255,255,.55), transparent 67%);
}
.portrait-stage .avatar-svg { position: relative; z-index: 2; width: 98%; height: 500px; max-height: 98%; margin-bottom: -61px; filter: drop-shadow(0 14px 10px rgba(83,46,63,.18)); }
.stage-sticker {
  position: absolute; z-index: 4; left: 12px; bottom: 12px;
  padding: 6px 9px; border-radius: 10px; background: rgba(255,251,242,.9);
  border: 1px solid rgba(81,59,81,.16); font-size: 8px; color: var(--ink-soft);
  box-shadow: 0 2px 0 rgba(81,59,81,.08);
}
.stage-sticker b { color: var(--ink); }
.stage-heart {
  position: absolute; z-index: 4; top: 12px; right: 12px;
  display: flex; align-items: center; gap: 4px; padding: 5px 9px;
  border-radius: 99px; background: rgba(255,251,242,.92); border: 1px solid rgba(81,59,81,.15);
  font-family: var(--font-display); font-size: 12px; color: var(--pink-deep);
}
.stage-heart .icon { fill: currentColor; width: 14px; height: 14px; }
.profile-panel { display: flex; flex-direction: column; gap: 11px; }
.profile-title-card {
  background: var(--paper); border: 1.5px solid rgba(81,59,81,.19); border-radius: 22px;
  padding: 17px 18px; box-shadow: var(--shadow-card);
}
.profile-title-top { display: flex; justify-content: space-between; gap: 12px; align-items: flex-start; }
.profile-title-card h1 { font-size: clamp(29px, 3.4vw, 42px); line-height: .92; letter-spacing: -.05em; }
.profile-title-card h1 small { display: block; font-family: var(--font-body); font-size: 11px; letter-spacing: .01em; color: var(--ink-soft); margin-top: 6px; font-weight: 700; }
.profile-title-right { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; }
.big-hearts { display: flex; gap: 2px; color: #e8cdd5; }
.big-hearts .icon { width: 18px; height: 18px; fill: none; }
.big-hearts .filled { color: #e5678d; fill: currentColor; }
.profile-tags { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 9px; }
.profile-affection { margin-top: 12px; }
.profile-affection .affection-line b { font-size: 13px; }
.dialogue-card {
  position: relative; background: #fff7ef; border: 1.5px solid rgba(81,59,81,.17);
  border-radius: 18px; padding: 13px 16px 14px; box-shadow: 0 3px 0 rgba(81,59,81,.06);
}
.dialogue-card::before {
  content: ""; position: absolute; left: 28px; top: -8px; width: 14px; height: 14px;
  background: #fff7ef; border-left: 1.5px solid rgba(81,59,81,.17); border-top: 1.5px solid rgba(81,59,81,.17);
  transform: rotate(45deg);
}
.dialogue-card .q-label { display: flex; align-items: center; gap: 5px; font-size: 8px; letter-spacing: .1em; text-transform: uppercase; color: var(--pink-deep); font-weight: 900; margin-bottom: 5px; }
.dialogue-card p { font-family: Georgia, "Times New Roman", serif; font-size: 15px; font-style: italic; line-height: 1.45; color: #59404f; }
.dialogue-card .q-meta { margin-top: 6px; font-size: 8px; color: var(--ink-faint); }
.profile-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.pstat {
  background: #fffdf8; border: 1.5px solid rgba(81,59,81,.12); border-radius: 13px;
  padding: 8px 10px; display: flex; align-items: center; gap: 7px;
}
.pstat .pstat-icon { width: 27px; height: 27px; border-radius: 8px; background: #fbe9ee; color: var(--pink-deep); display: flex; align-items: center; justify-content: center; }
.pstat small { display: block; font-size: 7px; letter-spacing: .09em; color: var(--ink-faint); font-weight: 900; text-transform: uppercase; }
.pstat b { display: block; font-size: 11px; margin-top: 1px; }
.action-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.action-grid .btn { min-height: 48px; flex-direction: column; gap: 3px; font-size: 10px; padding: 7px 5px; }
.action-grid .btn .icon { width: 18px; height: 18px; }
.action-grid .btn.wide { grid-column: span 2; }
.action-note { font-size: 8.5px; color: var(--ink-faint); text-align: center; margin-top: 6px; }
.profile-lower { display: grid; grid-template-columns: 1.2fr .8fr; gap: 12px; margin-top: 13px; }
.about-card { background: var(--paper); border: 1.5px solid rgba(81,59,81,.15); border-radius: 18px; padding: 14px 16px; box-shadow: 0 3px 0 rgba(81,59,81,.05); }
.about-card h3 { font-size: 12px; margin-bottom: 7px; display: flex; align-items: center; gap: 5px; }
.about-card p { font-size: 10px; line-height: 1.55; color: var(--ink-soft); }
.likes-list { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 7px; }
.likes-list .tag { font-size: 8px; }
.like { display: flex; align-items: center; gap: 4px; font-size: 9px; color: var(--ink-soft); }
.like .icon { width: 12px; height: 12px; color: var(--pink-deep); }
.relationship-track { display: flex; gap: 4px; margin-top: 8px; }
.relationship-track span { flex: 1; height: 6px; border-radius: 99px; background: #f1e2e5; }
.relationship-track span.on { background: linear-gradient(90deg, #f7a6bc, #e3678e); }
.married-card {
  background: linear-gradient(145deg, #fff2d0, #ffe6e6);
  border-color: #dfbd85;
}
.married-card h3 { color: #8f5b29; }
.married-card .btn { margin-top: 8px; }

/* ---------- Family ---------- */
.family-summary { display: grid; grid-template-columns: repeat(4, 1fr); gap: 9px; margin-bottom: 15px; }
.summary-stat {
  padding: 12px 13px; border-radius: 16px;
  background: var(--paper); border: 1.5px solid rgba(81,59,81,.15);
  box-shadow: 0 3px 0 rgba(81,59,81,.05);
}
.summary-stat .sum-icon { width: 30px; height: 30px; border-radius: 9px; display: flex; align-items: center; justify-content: center; margin-bottom: 7px; background: #ffe6ed; color: #b9476d; }
.summary-stat.mint .sum-icon { background: #e2f4ec; color: #4f927f; }
.summary-stat.butter .sum-icon { background: #fff2c9; color: #9c7020; }
.summary-stat.violet .sum-icon { background: #ece7fa; color: #6e5baa; }
.summary-stat small { display: block; font-size: 7.5px; letter-spacing: .1em; text-transform: uppercase; font-weight: 900; color: var(--ink-faint); }
.summary-stat b { display: block; font-family: var(--font-display); font-size: 22px; line-height: 1.1; margin-top: 2px; }
.summary-stat span { display: block; font-size: 8px; color: var(--ink-soft); margin-top: 2px; }
.family-layout { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(250px, .8fr); gap: 14px; align-items: start; }
.family-section-title { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 8px; }
.family-section-title h2 { font-size: 16px; display: flex; align-items: center; gap: 6px; }
.family-section-title h2 .icon { color: var(--pink-deep); }
.spouse-list { display: grid; grid-template-columns: repeat(2, 1fr); gap: 9px; }
.spouse-card {
  display: flex; gap: 9px; padding: 9px;
  border: 1.5px solid rgba(81,59,81,.16); border-radius: 17px;
  background: var(--paper); box-shadow: 0 3px 0 rgba(81,59,81,.06);
}
.spouse-face { width: 82px; height: 100px; flex: 0 0 auto; border-radius: 12px; overflow: hidden; background: #ffe3d7; border: 1px solid rgba(81,59,81,.1); }
.spouse-face .avatar-svg { width: 135%; height: 135%; transform: translate(-13%, 0); }
.spouse-copy { min-width: 0; display: flex; flex-direction: column; }
.spouse-copy h3 { font-size: 14px; line-height: 1; }
.spouse-copy small { font-size: 8px; color: var(--ink-soft); margin-top: 3px; }
.spouse-copy .affection-line { margin-top: auto; }
.spouse-copy .btn { margin-top: 5px; }
.child-list { display: grid; gap: 7px; }
.child-card {
  display: flex; align-items: center; gap: 8px; padding: 8px 9px;
  border: 1.5px solid rgba(81,59,81,.13); border-radius: 14px; background: var(--paper);
}
.child-face { width: 50px; height: 58px; flex: 0 0 auto; border-radius: 10px; overflow: hidden; background: #ffedd8; border: 1px solid rgba(81,59,81,.1); }
.child-face .avatar-svg { width: 145%; height: 145%; transform: translate(-15%, 1%); }
.child-copy { min-width: 0; flex: 1; }
.child-copy h3 { font-size: 12px; line-height: 1; display: flex; align-items: center; gap: 5px; }
.child-copy h3 .chip { font-size: 6.5px; padding: 2px 5px; min-height: 16px; }
.child-copy small { display: block; font-size: 8px; color: var(--ink-soft); margin-top: 3px; }
.child-copy .child-income { font-size: 8px; color: var(--mint-deep); font-weight: 800; margin-top: 2px; }
.child-status { display: flex; align-items: center; gap: 4px; font-size: 7.5px; color: var(--ink-faint); text-align: right; max-width: 78px; line-height: 1.25; }
.grow-meter { width: 47px; height: 5px; background: #eee0e4; border-radius: 99px; overflow: hidden; margin-top: 3px; }
.grow-meter i { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #f2a5b8, #dd6d91); }
.legacy-banner {
  display: flex; gap: 11px; align-items: center; padding: 13px;
  border-radius: 18px; border: 1.5px solid #e7ca95;
  background: linear-gradient(145deg, #fff7db, #ffe9cf);
}
.legacy-banner .legacy-icon { width: 42px; height: 42px; border-radius: 50%; display: flex; align-items: center; justify-content: center; background: #f7d487; color: #85561e; flex: 0 0 auto; }
.legacy-banner h3 { font-size: 12px; color: #805221; }
.legacy-banner p { font-size: 9px; line-height: 1.45; color: #8f7046; margin-top: 3px; }
.income-card { background: #fff9ee; }
.income-row { display: flex; align-items: center; justify-content: space-between; font-size: 9.5px; padding: 5px 0; border-bottom: 1px dashed rgba(81,59,81,.12); }
.income-row:last-child { border: 0; }
.income-row b { color: var(--mint-deep); }
.family-empty { padding: 24px 16px; border: 1.5px dashed rgba(81,59,81,.18); border-radius: 15px; text-align: center; }
.family-empty p { font-size: 9px; line-height: 1.45; color: var(--ink-soft); }

/* ---------- Perks ---------- */
.perks-hero {
  display: flex; align-items: center; gap: 14px; margin-bottom: 16px; padding: 15px 17px;
  border-radius: 21px; border: 1.5px solid #dfc38e;
  background:
    radial-gradient(circle at 88% 20%, rgba(255,255,255,.6), transparent 20%),
    linear-gradient(135deg, #fff5d6, #ffe6d0);
  box-shadow: 0 4px 0 rgba(81,59,81,.08);
}
.perks-hero .perk-hero-icon { width: 48px; height: 48px; border-radius: 15px; background: #f4c862; color: #6f4912; display: flex; align-items: center; justify-content: center; border: 2px solid #92621e; box-shadow: 0 3px 0 #b7872f; flex: 0 0 auto; }
.perks-hero h2 { font-size: 18px; color: #6d4917; }
.perks-hero p { font-size: 9.5px; color: #8a6c3d; line-height: 1.45; margin-top: 3px; }
.perk-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 11px; }
.perk-card {
  position: relative; overflow: hidden;
  padding: 15px 14px 13px;
  border-radius: 21px; border: 1.5px solid rgba(81,59,81,.2);
  background: var(--paper); box-shadow: var(--shadow-card);
}
.perk-card::before {
  content: ""; position: absolute; right: -30px; top: -35px; width: 100px; height: 100px;
  border-radius: 50%; background: var(--perk-soft, #fff0d2); opacity: .7;
}
.perk-card .perk-icon { position: relative; width: 42px; height: 42px; border-radius: 13px; display: flex; align-items: center; justify-content: center; background: var(--perk-soft, #fff0d2); color: var(--perk, #c68a2b); border: 1.5px solid rgba(81,59,81,.16); margin-bottom: 8px; }
.perk-card h3 { position: relative; font-size: 16px; }
.perk-card .perk-sub { font-size: 8.5px; color: var(--ink-soft); margin-top: 2px; }
.perk-rank-row { display: flex; align-items: center; justify-content: space-between; gap: 5px; margin: 11px 0 6px; }
.perk-rank-row b { font-family: var(--font-display); font-size: 22px; line-height: 1; }
.perk-rank-row b small { font-family: var(--font-body); font-size: 9px; color: var(--ink-faint); font-weight: 700; }
.perk-rank-row .prestige-tag { font-size: 7px; font-weight: 900; color: #7661a6; background: #eee9fb; padding: 3px 6px; border-radius: 99px; }
.pips { display: grid; grid-template-columns: repeat(10, 1fr); gap: 3px; }
.pips i { height: 7px; border-radius: 2px; background: #f0e3e6; }
.pips i.on { background: var(--perk, #c68a2b); box-shadow: inset 0 1px 0 rgba(255,255,255,.4); }
.pips i.prestige { box-shadow: 0 0 0 1.5px #9d88c8; }
.perk-effect {
  margin: 10px 0 8px; padding: 7px 8px; border-radius: 9px;
  background: var(--perk-soft, #fff0d2); color: #76501e;
  font-size: 8.5px; line-height: 1.35; font-weight: 800;
}
.perk-next { font-size: 8px; color: var(--ink-faint); margin-bottom: 7px; line-height: 1.35; min-height: 22px; }
.perk-card .btn { width: 100%; }
.perk-card .prestige-btn { margin-top: 5px; }
.prestige-rules {
  margin-top: 14px; padding: 14px 16px; border-radius: 18px;
  background: #f1eafb; border: 1.5px solid #d4c4ed;
  display: grid; grid-template-columns: auto 1fr; gap: 12px; align-items: start;
}
.prestige-rules .pr-icon { width: 42px; height: 42px; border-radius: 50%; background: #dfd0f5; color: #6b54a0; display: flex; align-items: center; justify-content: center; }
.prestige-rules h3 { font-size: 13px; color: #5e4b8a; }
.prestige-rules p { font-size: 9px; line-height: 1.5; color: #746392; margin-top: 2px; }
.prestige-rules .prestige-slots { display: flex; gap: 5px; margin-top: 6px; }
.prestige-slots i { width: 22px; height: 8px; border-radius: 99px; background: #d8c9ea; }
.prestige-slots i.on { background: #8268bd; }
.perk-locked { font-size: 8px; color: var(--ink-faint); text-align: center; margin-top: 4px; }

/* ---------- Mirror / wardrobe ---------- */
.mirror-layout { display: grid; grid-template-columns: minmax(300px, .9fr) minmax(320px, 1.1fr); gap: 15px; }
.mirror-stage {
  position: relative; min-height: 480px; overflow: hidden;
  border: 2px solid var(--line); border-radius: 25px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.45), transparent 30%),
    linear-gradient(160deg, #ecdff7, #ffdce7 60%, #ffe9cc);
  box-shadow: 0 6px 0 rgba(81,59,81,.13), 0 20px 40px rgba(81,59,81,.1);
  display: flex; align-items: flex-end; justify-content: center;
}
.mirror-stage::before {
  content: ""; position: absolute; left: 13%; top: 9%; width: 74%; height: 79%;
  border-radius: 50% 50% 12% 12%; border: 8px solid rgba(255,251,241,.5); box-shadow: inset 0 0 0 2px rgba(81,59,81,.16);
}
.mirror-stage .avatar-svg { position: relative; z-index: 2; width: 92%; height: 500px; margin-bottom: -54px; }
.mirror-sticker { position: absolute; z-index: 4; top: 13px; left: 13px; }
.mirror-side { display: flex; flex-direction: column; gap: 11px; }
.mirror-summary { padding: 16px; }
.mirror-summary h2 { font-size: 24px; }
.mirror-summary p { font-size: 10px; color: var(--ink-soft); line-height: 1.5; margin-top: 4px; }
.mirror-details { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin-top: 13px; }
.mirror-detail { padding: 8px 9px; border-radius: 11px; background: #faf2ed; border: 1px solid rgba(81,59,81,.1); }
.mirror-detail small { display: block; font-size: 7px; color: var(--ink-faint); text-transform: uppercase; letter-spacing: .09em; font-weight: 900; }
.mirror-detail b { display: block; font-size: 10px; margin-top: 2px; }
.outfit-shelf { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; margin-top: 10px; }
.shelf-item { padding: 6px 3px; border: 1px solid rgba(81,59,81,.12); border-radius: 9px; background: #fffaf4; font-size: 7px; text-align: center; color: var(--ink-soft); line-height: 1.15; }
.shelf-item b { display: block; width: 22px; height: 22px; border-radius: 50%; margin: 0 auto 3px; background: var(--swatch, #f2a3ba); border: 1px solid rgba(81,59,81,.15); }
.mirror-actions { display: grid; gap: 6px; }
.change-fee { display: flex; align-items: center; gap: 5px; font-size: 8px; color: var(--ink-faint); justify-content: center; margin-top: 4px; }
.dressing-note {
  padding: 12px 14px; border-radius: 15px;
  background: #fff6d9; border: 1.5px solid #ecd28e;
  font-size: 9px; line-height: 1.5; color: #896b2d;
}
.dressing-note b { color: #704f14; }

/* ---------- Calendar / time modal bits ---------- */
.sleep-report { display: grid; gap: 8px; }
.sleep-stat-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 9px 11px; border-radius: 12px; background: #fff8ee; border: 1px solid rgba(81,59,81,.1); }
.sleep-stat-row .ssr-label { display: flex; align-items: center; gap: 7px; font-size: 10px; color: var(--ink-soft); }
.sleep-stat-row .ssr-label .icon { color: var(--pink-deep); width: 15px; height: 15px; }
.sleep-stat-row b { font-size: 11px; }
.day-report {
  padding: 13px 15px; border-radius: 15px;
  background: linear-gradient(150deg, #fff3d2, #ffe8dc);
  border: 1.5px solid #e5c28d;
}
.day-report h3 { font-size: 14px; color: #825721; }
.day-report p { font-size: 9px; color: #8b6d41; line-height: 1.45; margin-top: 3px; }
.day-report .payday { display: flex; align-items: baseline; gap: 6px; margin-top: 7px; }
.day-report .payday b { font-family: var(--font-display); font-size: 24px; color: #4f7a61; }
.day-report .payday small { font-size: 8px; color: #7d7460; }

/* ---------- Gifts ---------- */
.gift-wallet { display: flex; align-items: center; gap: 6px; padding: 6px 10px; border-radius: 99px; background: #fff1c8; color: #8f641b; font-size: 9px; font-weight: 900; }
.gift-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.gift-card {
  display: flex; flex-direction: column; gap: 4px; align-items: flex-start;
  padding: 11px; text-align: left;
  border: 1.5px solid rgba(81,59,81,.16); border-radius: 15px; background: #fffdf8;
  transition: .15s ease;
}
.gift-card:hover { border-color: var(--gift, #f19ab1); transform: translateY(-2px); box-shadow: 0 4px 0 rgba(81,59,81,.07); }
.gift-card .gift-top { width: 100%; display: flex; justify-content: space-between; align-items: flex-start; }
.gift-art {
  width: 39px; height: 39px; border-radius: 12px; display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--gift, #f19ab1) 20%, white); color: var(--gift, #b9476d);
  border: 1px solid color-mix(in srgb, var(--gift, #f19ab1) 45%, white);
}
.gift-price { font-family: var(--font-display); font-size: 11px; color: #8c661f; }
.gift-card b { font-size: 10px; line-height: 1.1; margin-top: 3px; }
.gift-card small { font-size: 7.5px; line-height: 1.35; color: var(--ink-soft); }
.gift-hearts { font-size: 8px; color: var(--pink-deep); font-weight: 900; margin-top: auto; padding-top: 5px; }
.gift-hearts .icon { width: 10px; height: 10px; fill: currentColor; vertical-align: -1px; }
.gift-liked { color: #b27720; }
.gift-hint { margin-top: 10px; padding: 8px 10px; background: #fff8e8; border-radius: 10px; font-size: 8px; color: #94733d; line-height: 1.4; }

/* ---------- Date modal ---------- */
.date-grid { display: grid; gap: 8px; }
.date-option {
  display: flex; align-items: center; gap: 10px; padding: 11px 12px;
  border: 1.5px solid rgba(81,59,81,.15); border-radius: 15px; background: #fffdf8; text-align: left;
  transition: .15s ease;
}
.date-option:hover { border-color: #df9baf; background: #fff9f5; transform: translateX(2px); }
.date-option .date-icon { width: 41px; height: 41px; border-radius: 13px; background: var(--date-soft, #ffe8ef); color: var(--date-ink, #b9476d); display: flex; align-items: center; justify-content: center; flex: 0 0 auto; }
.date-option .date-copy { flex: 1; min-width: 0; }
.date-option .date-copy b { display: block; font-size: 11px; }
.date-option .date-copy small { display: block; font-size: 8px; color: var(--ink-soft); margin-top: 2px; line-height: 1.35; }
.date-option .date-cost { font-size: 9px; font-weight: 900; color: #8b661e; white-space: nowrap; }

/* ---------- Holiday / welcome / endings ---------- */
.holiday-modal {
  overflow: hidden;
  background:
    radial-gradient(circle at 78% 12%, rgba(255,255,255,.6), transparent 17%),
    linear-gradient(155deg, #fff5dd, #ffdde6);
}
.holiday-banner { display: flex; gap: 13px; align-items: center; }
.holiday-emblem {
  width: 66px; height: 66px; border-radius: 20px; flex: 0 0 auto;
  display: flex; align-items: center; justify-content: center;
  background: var(--holiday, #e37c9e); color: #fff;
  border: 2px solid var(--line); box-shadow: 0 4px 0 rgba(81,59,81,.16), inset 0 2px 0 rgba(255,255,255,.3);
}
.holiday-banner h2 { font-size: 27px; line-height: 1; }
.holiday-banner p { font-size: 10px; line-height: 1.45; color: var(--ink-soft); margin-top: 4px; }
.holiday-newbies { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 15px; }
.holiday-person { flex: 1 1 45%; display: flex; align-items: center; gap: 7px; padding: 7px; border-radius: 12px; background: rgba(255,253,248,.8); border: 1px solid rgba(81,59,81,.12); }
.holiday-person .hp-face { width: 43px; height: 49px; border-radius: 9px; overflow: hidden; background: #ffe9dc; }
.holiday-person .hp-face .avatar-svg { width: 140%; height: 140%; transform: translate(-14%, 0); }
.holiday-person b { display: block; font-size: 10px; }
.holiday-person small { display: block; font-size: 7px; color: var(--ink-soft); margin-top: 2px; }
.welcome-card { text-align: center; padding: 10px 3px 0; }
.welcome-card .welcome-badge { width: 72px; height: 72px; border-radius: 50%; margin: 0 auto 12px; display: flex; align-items: center; justify-content: center; background: #ffe6ed; color: var(--pink-deep); border: 2px dashed #e7a2b5; }
.welcome-card h2 { font-size: 27px; }
