/* Full-screen character creator and makeover studio. */
.creator-overlay {
  position: fixed; inset: 0; z-index: 850;
  display: flex; flex-direction: column;
  overflow: hidden;
  background:
    radial-gradient(circle at 18% 13%, rgba(255,255,255,.72) 0 1px, transparent 2px),
    radial-gradient(circle at 81% 21%, rgba(255,255,255,.5) 0 1px, transparent 2px),
    linear-gradient(160deg, #d8e9e6 0%, #c9e0eb 24%, #ffd7c4 62%, #f4aebd 100%);
  background-size: 160px 130px, 220px 190px, auto;
}
.creator-overlay::before {
  content: ""; position: absolute; z-index: 0; left: -10%; right: -10%; bottom: -17%;
  height: 42%; border-radius: 50% 50% 0 0;
  background:
    radial-gradient(ellipse at 30% 100%, rgba(112,160,124,.45), transparent 63%),
    radial-gradient(ellipse at 76% 100%, rgba(159,183,119,.42), transparent 64%);
  pointer-events: none;
}
.creator-overlay::after {
  content: ""; position: absolute; z-index: 0; inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.7' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.18'/%3E%3C/svg%3E");
  mix-blend-mode: multiply; opacity: .13; pointer-events: none;
}
.creator-top {
  position: relative; z-index: 5;
  min-height: 66px; display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 10px clamp(16px, 3vw, 42px);
}
.creator-top-left { display: flex; align-items: center; gap: 12px; }
.creator-top .brand-mark { width: 35px; height: 35px; }
.creator-top .brand-mark .brand-heart { font-size: 18px; }
.creator-title { display: grid; line-height: 1.05; }
.creator-title small { font-size: 8px; font-weight: 900; letter-spacing: .16em; color: #8c6472; }
.creator-title b { font-family: var(--font-display); font-size: 14px; color: #563c4b; }
.creator-top-right { display: flex; gap: 7px; align-items: center; }
.creator-fee-chip {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 5px 10px; border-radius: 99px; font-size: 9px; font-weight: 900;
  background: #fff5dd; border: 1.5px solid #e7c98b; color: #8a621c;
}
.creator-close {
  width: 36px; height: 36px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: rgba(255,251,241,.78); border: 1.5px solid rgba(81,59,81,.22);
  color: var(--ink-soft); box-shadow: 0 2px 0 rgba(81,59,81,.1);
}
.creator-close:hover { background: #fff; color: var(--pink-deep); }
.creator-shell {
  position: relative; z-index: 3;
  flex: 1; min-height: 0;
  width: min(1320px, 100%); margin: 0 auto;
  display: grid; grid-template-columns: minmax(330px, .82fr) minmax(400px, 1.18fr);
  gap: clamp(12px, 2.2vw, 28px);
  padding: 0 clamp(14px, 3vw, 40px) clamp(14px, 2.5vh, 28px);
}
.creator-stage {
  position: relative; min-height: 0;
  display: flex; align-items: flex-end; justify-content: center;
  padding: 8px;
}
.creator-halo {
  position: absolute; z-index: 0; width: min(105%, 500px); aspect-ratio: 1;
  left: 50%; top: 47%; translate: -50% -50%;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 50%, rgba(255,252,233,.92) 0 27%, rgba(255,228,207,.62) 50%, rgba(255,217,218,.12) 70%),
    repeating-conic-gradient(from 10deg, rgba(255,255,255,.33) 0 7deg, transparent 7deg 14deg);
  box-shadow: inset 0 0 0 13px rgba(255,251,238,.2), 0 20px 50px rgba(96,57,75,.12);
  animation: halo-turn 60s linear infinite;
}
@keyframes halo-turn { to { rotate: 360deg; } }
.creator-halo::after {
  content: ""; position: absolute; inset: 12%; border-radius: 50%;
  border: 1.5px dashed rgba(148,91,102,.22);
}
.creator-preview {
