  .energy-copy .energy-bar { width: 31px; }
  .top-actions .icon-btn { width: 30px; height: 30px; }
  .logo { font-size: 54px; }
  .hero-stage { min-height: 335px; }
  .hero-cast { height: 335px; }
  .hero-person:nth-child(1), .hero-person:nth-child(3) { width: 145px; }
  .hero-person:nth-child(2) { width: 185px; }
  .hero-person:nth-child(4) { width: 125px; }
  .sticker-cal { display: none; }
  .suitor-portrait { height: 210px; }
  .date-pill { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
  }
}

/* Big screens: give the town some breathing room. */
@media (min-width: 1500px) {
  .game-shell { grid-template-columns: 248px minmax(0, 1fr) 312px; }
  .view { padding: 27px 30px 42px; max-width: 1220px; }
}

