/* App frame: topbar, navigation, scrolling stage, and the daily rail. */
.game {
  height: 100dvh;
  display: grid;
  grid-template-rows: 72px minmax(0, 1fr);
  background: #f7e8df;
  overflow: hidden;
  position: relative;
}
.game::before {
  content: "";
  position: fixed; inset: 0; pointer-events: none; z-index: 0;
  background:
    radial-gradient(circle at 9% 18%, rgba(255,255,255,.7) 0 1px, transparent 2px),
    radial-gradient(circle at 63% 7%, rgba(255,255,255,.45) 0 1px, transparent 2px);
  background-size: 150px 120px, 220px 170px;
  opacity: .5;
}
.topbar {
  position: relative; z-index: 20;
  display: grid; grid-template-columns: 230px minmax(0, 1fr) auto;
  align-items: center; gap: 14px;
  height: 72px;
  padding: 0 20px;
  background: rgba(255, 252, 245, .9);
  border-bottom: 1.5px solid rgba(81, 59, 81, .18);
  backdrop-filter: blur(14px) saturate(1.15);
  box-shadow: 0 4px 18px rgba(99, 56, 74, .06);
}
.top-brand {
  display: flex; align-items: center; gap: 9px;
  border: 0; background: none; padding: 0; text-align: left;
}
.top-brand:hover .top-brand-copy b { color: var(--pink-deep); }
.top-brand-copy { display: grid; line-height: 1.1; }
.top-brand-copy b { font-family: var(--font-display); font-size: 11px; letter-spacing: .16em; transition: color .16s; }
.top-brand-copy small { font-size: 8px; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-faint); margin-top: 3px; }
.hud {
  justify-self: center;
  display: flex; align-items: center; gap: 7px; flex-wrap: nowrap;
}
.hud-pill {
  display: flex; align-items: center; gap: 8px;
  min-height: 44px; padding: 5px 12px 5px 7px;
  border-radius: 15px; border: 1.5px solid rgba(81,59,81,.14);
  background: rgba(255,255,255,.68);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.8);
}
.hud-pill > span:not(.hud-icon):not(.energy-copy) { display: grid; line-height: 1.05; }
.hud-pill small { font-size: 7.5px; letter-spacing: .12em; color: var(--ink-faint); font-weight: 900; }
.hud-pill b { font-family: var(--font-display); font-size: 12.5px; white-space: nowrap; }
.hud-icon {
  width: 30px; height: 30px; border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  background: #ffe9ef; color: #b9476d; font-family: var(--font-display); font-size: 15px;
}
.money-pill .hud-icon { background: #fff1c8; color: #94661b; }
.date-pill .hud-icon { background: #e8f4f7; color: #407f93; }
.energy-pill .hud-icon { background: #e7f7ef; color: #3e8a73; }
.energy-pill { padding-right: 11px; }
.energy-copy { display: grid; gap: 3px; min-width: 62px; }
.energy-bar { width: 68px; height: 6px; background: #eadfe4; border-radius: 99px; overflow: hidden; }
.energy-bar i { display: block; height: 100%; background: linear-gradient(90deg, #9edfc9, #55aa8c); border-radius: 99px; transition: width .35s; }
.energy-pill.low .energy-bar i { background: linear-gradient(90deg, #ffb071, #e86a57); }
.energy-pill > b { color: var(--mint-deep); }
.energy-pill.low > b { color: #bb513c; }
.top-actions { display: flex; gap: 6px; align-items: center; }
.top-actions .icon-btn { width: 36px; height: 36px; }

.game-shell {
  position: relative; z-index: 1;
  display: grid;
  grid-template-columns: 232px minmax(0, 1fr) 292px;
  min-height: 0;
}
.sidebar {
  min-height: 0;
  display: flex; flex-direction: column;
  padding: 16px 13px;
  background: rgba(255, 250, 241, .84);
  border-right: 1.5px solid rgba(81,59,81,.13);
  overflow-y: auto;
}
.sidebar-me {
  margin-bottom: 14px;
}
.me-card {
  display: flex; align-items: center; gap: 9px; position: relative;
  padding: 8px 9px 8px 7px;
  background: linear-gradient(135deg, #fffdf8, #fff1eb);
  border: 1.5px solid rgba(81,59,81,.18);
  border-radius: 17px;
  box-shadow: 0 3px 0 rgba(81,59,81,.08);
}
.me-portrait {
  width: 49px; height: 49px; border-radius: 13px; overflow: hidden;
  background: linear-gradient(160deg, #ffd8df, #ffeed9);
  border: 1.5px solid rgba(81,59,81,.16); flex: 0 0 auto;
}
.me-portrait .avatar-svg { width: 100%; height: 100%; transform: scale(1.2) translateY(5%); }
.me-copy { min-width: 0; display: grid; line-height: 1.1; }
.me-copy small { font-size: 7.5px; font-weight: 900; letter-spacing: .11em; color: var(--ink-faint); }
.me-copy b { font-family: var(--font-display); font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin: 2px 0; }
.me-copy span { font-size: 8.5px; color: var(--ink-soft); white-space: nowrap; }
.me-edit {
  position: absolute; right: 6px; bottom: 6px; width: 22px; height: 22px;
  border-radius: 50%; border: 1px solid rgba(81,59,81,.15); background: #fff;
  display: flex; align-items: center; justify-content: center; color: var(--ink-soft);
}
.me-edit:hover { color: var(--pink-deep); }
.nav-list { display: flex; flex-direction: column; gap: 4px; }
.nav-item {
  position: relative; width: 100%;
  display: flex; align-items: center; gap: 9px;
  min-height: 46px; padding: 7px 9px;
  border: 1.5px solid transparent; border-radius: 13px;
  background: transparent; color: var(--ink-soft); text-align: left;
  transition: .16s ease;
}
.nav-item:hover { background: rgba(255,255,255,.7); color: var(--ink); }

