.hero-person {
  position: absolute; bottom: 2%;
  width: clamp(220px, 24vw, 315px); height: 84%;
  filter: drop-shadow(0 16px 18px rgba(94,49,68,.22));
  animation: hero-bob 5.5s ease-in-out infinite;
  transform-origin: 50% 100%;
}
.hero-person:nth-child(1) { left: 0; bottom: 1%; width: clamp(195px, 21vw, 280px); rotate: -5deg; animation-delay: -1.5s; }
.hero-person:nth-child(2) { left: 50%; translate: -50% 0; width: clamp(240px, 26vw, 345px); z-index: 4; bottom: 0; }
.hero-person:nth-child(3) { right: 0; bottom: 3%; width: clamp(195px, 21vw, 280px); rotate: 5deg; animation-delay: -3s; }
.hero-person:nth-child(4) { left: 35%; bottom: 22%; width: clamp(160px, 17vw, 225px); z-index: 5; rotate: 7deg; animation-delay: -4s; }
@keyframes hero-bob { 50% { transform: translateY(-9px); } }
.hero-person::after {
  content: ""; position: absolute; left: 13%; right: 13%; bottom: -1%; height: 20px;
  background: radial-gradient(ellipse, rgba(98, 47, 69, .23), transparent 67%);
  border-radius: 50%;
}
.hero-portrait {
  position: absolute; inset: 0 4% 0;
  display: flex; align-items: flex-end; justify-content: center;
  border-radius: 44% 44% 24% 24%;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(255,248,234,.26), rgba(255,211,215,.38));
  border: 2px solid rgba(95,52,70,.32);
  box-shadow: inset 0 0 0 7px rgba(255,251,240,.23);
}
.hero-portrait .avatar-svg { height: 116%; width: 118%; transform: translateY(4%); }
.hero-center .hero-portrait { border-radius: 46% 46% 22% 22%; background: linear-gradient(180deg, rgba(255,248,217,.2), rgba(255,183,194,.45)); }
.hero-person .name-tag {
  position: absolute; left: 50%; bottom: -13px; translate: -50%;
  z-index: 7; display: inline-flex; align-items: center; gap: 5px;
  padding: 6px 11px; border-radius: 999px; white-space: nowrap;
  background: #fffaf0; border: 1.5px solid var(--line);
  box-shadow: 0 3px 0 rgba(81,59,81,.15);
  font-family: var(--font-display); font-size: 11px;
}
.hero-person .name-tag small { font-family: var(--font-body); font-size: 8px; letter-spacing: .06em; color: var(--ink-soft); text-transform: uppercase; }
.hero-sticker {
  position: absolute; z-index: 8; display: flex; align-items: center; gap: 8px;
  padding: 9px 12px 9px 9px; border-radius: 15px;
  background: rgba(255, 251, 242, .92); border: 1.5px solid var(--line);
  box-shadow: 0 4px 0 rgba(81,59,81,.12), 0 13px 28px rgba(86,43,65,.15);
  backdrop-filter: blur(8px);
  animation: sticker-float 6s ease-in-out infinite;
}
.hero-sticker b { display: block; font-family: var(--font-display); font-size: 10px; line-height: 1.15; }
.hero-sticker small { display: block; font-size: 8px; color: var(--ink-soft); margin-top: 2px; }
.sticker-icon {
  width: 28px; height: 28px; border-radius: 9px;
  display: flex; align-items: center; justify-content: center;
  background: #ffe3ea; color: #b9476d; font-size: 15px;
}
.sticker-date { left: -2%; top: 17%; rotate: -4deg; animation-delay: -2s; }
.sticker-heart { right: -1%; top: 39%; rotate: 3.5deg; animation-delay: -4s; }
.sticker-heart .sticker-icon { background: #ffe6eb; color: #e35a84; }
.sticker-cal { right: 3%; bottom: 1%; rotate: -1.5deg; animation-delay: -1s; }
.sticker-cal .sticker-icon { background: #fff2c3; color: #a6741d; }
@keyframes sticker-float { 50% { translate: 0 -7px; } }
.hero-spark { position: absolute; z-index: 9; color: #fff8c7; text-shadow: 0 2px 0 #a25e59; font-size: 24px; animation: twinkle 3.5s ease-in-out infinite; }
.hero-spark.s1 { left: 7%; top: 7%; animation-delay: -1s; }
.hero-spark.s2 { right: 8%; top: 13%; font-size: 31px; animation-delay: -2.4s; }
.hero-spark.s3 { left: 12%; bottom: 30%; font-size: 17px; animation-delay: -.8s; }
.hero-spark.s4 { right: 22%; bottom: 18%; font-size: 19px; animation-delay: -3.2s; }

.splash-footer {
  position: relative; z-index: 5;
  display: flex; justify-content: space-between; align-items: center; gap: 14px;
  padding: 12px clamp(22px, 4vw, 62px) max(14px, env(safe-area-inset-bottom));
  color: rgba(255, 251, 242, .85); font-size: 9px; font-weight: 800;
  letter-spacing: .08em; text-transform: uppercase;
  text-shadow: 0 1px 0 rgba(98, 43, 65, .35);
}
.splash-footer-left { display: flex; align-items: center; gap: 7px; }
.splash-footer .mini-heart { color: #ffc3d3; }

@media (max-width: 980px) {
  .splash-main { grid-template-columns: 1fr; padding-top: 2px; }
  .splash-copy { max-width: 620px; margin: 0 auto; text-align: center; justify-items: center; }
  .splash-kicker, .splash-actions { justify-content: center; }
  .logo { margin-left: 0; }
  .logo-hollow { margin-left: 0; }
  .splash-tagline, .splash-copy-small { margin-left: auto; margin-right: auto; }
