62: }
63: .p1 { left: 7%; top: 25%; animation-delay: -2s; }
64: .p2 { left: 24%; top: 51%; transform: scale(.7); animation-delay: -7s; }
65: .p3 { left: 49%; top: 20%; transform: scale(.5); animation-delay: -4s; }
66: .p4 { left: 70%; top: 55%; animation-delay: -8s; }
67: .p5 { left: 86%; top: 33%; transform: scale(.6); animation-delay: -5s; }
68: .p6 { left: 37%; top: 76%; animation-delay: -9s; }
69: @keyframes petal-float {
70:   0% { translate: 0 -8vh; rotate: 0deg; opacity: 0; }
71:   15% { opacity: .85; }
72:   100% { translate: 8vw 82vh; rotate: 240deg; opacity: 0; }
73: }
74: .splash-grain {
75:   position: absolute; inset: 0; z-index: 3; pointer-events: none; opacity: .1;
76:   background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.45'/%3E%3C/svg%3E");
77:   mix-blend-mode: multiply;
78: }
79: 
80: .splash-nav {
81:   position: relative; z-index: 4;
82:   display: flex; align-items: center; justify-content: space-between;
83:   gap: 18px; padding: 20px clamp(22px, 4vw, 62px);
84: }
85: .splash-brand { display: flex; align-items: center; gap: 11px; }
86: .brand-mark {
87:   width: 40px; height: 40px; border-radius: 50%;
88:   display: inline-flex; align-items: center; justify-content: center;
89:   background: linear-gradient(150deg, #ffb1c2, #eb6c95);
90:   border: 2px solid var(--line);
91:   box-shadow: 0 3px 0 #9c3c5c, inset 0 2px 0 rgba(255,255,255,.5);
92:   color: white; transform: rotate(-7deg);
93: }
94: .brand-mark .brand-heart { font-size: 21px; line-height: 1; text-shadow: 0 1px 0 #9c3c5c; transform: rotate(7deg); }
95: .brand-mark.small { width: 33px; height: 33px; }
96: .brand-mark.small .brand-heart { font-size: 17px; }
97: .brand-word { font-family: var(--font-display); font-size: 13px; letter-spacing: .2em; color: #fffdf8; text-shadow: 0 1px 0 #9c5b6c, 0 2px 5px rgba(110,55,77,.2); }
98: .splash-meta { display: flex; gap: 8px; }
99: .meta-pill {
100:   display: inline-flex; align-items: center; min-height: 27px; padding: 5px 11px;
101:   border-radius: 999px; background: rgba(255,251,238,.68); border: 1.5px solid rgba(81,59,81,.35);
102:   font-size: 9px; font-weight: 900; letter-spacing: .12em; color: #6f4a60;
103:   backdrop-filter: blur(7px);
104: }
105: .meta-pill.hot { background: rgba(228, 96, 133, .88); border-color: #9e3e5e; color: #fff; text-shadow: 0 1px 0 rgba(103,31,57,.25); }
106: 
107: .splash-main {
108:   position: relative; z-index: 4;
109:   flex: 1;
110:   width: min(1340px, 100%);
111:   margin: 0 auto;
112:   padding: clamp(10px, 2vh, 32px) clamp(22px, 4vw, 64px) 30px;
113:   display: grid; grid-template-columns: minmax(340px, .9fr) minmax(380px, 1.15fr);
114:   align-items: center; gap: clamp(16px, 3vw, 60px);
115: }
116: .splash-copy { position: relative; z-index: 2; max-width: 570px; }
117: .splash-kicker {
118:   display: flex; align-items: center; gap: 8px;
119:   font-size: 10px; font-weight: 900; letter-spacing: .17em; color: #7d596a;
120:   text-transform: uppercase; margin-bottom: 9px;
121: }
122: .splash-kicker span { width: 24px; height: 1.5px; background: currentColor; opacity: .6; }
123: .logo {
124:   display: grid; line-height: .78;
125:   margin: 0 0 14px -4px;
126:   font-family: var(--font-display);
127:   font-size: clamp(67px, 8vw, 112px);
128:   font-weight: 900;
129:   letter-spacing: -.07em;
130:   color: #fff8ec;
131:   -webkit-text-stroke: clamp(2px, .26vw, 4px) #523444;
132:   paint-order: stroke fill;
133:   text-shadow: 0 5px 0 #b35d78, 0 10px 0 rgba(95,51,68,.22), 0 16px 24px rgba(91,41,59,.2);
134:   transform: rotate(-2.2deg);
135: }
136: .logo-maple { display: block; }
137: .logo-hollow {
138:   display: block; margin-left: clamp(32px, 4.5vw, 65px);
139:   color: #ffd9e0;
140:   -webkit-text-stroke-color: #67364f;
141:   text-shadow: 0 5px 0 #c45278, 0 10px 0 rgba(95,51,68,.22), 0 16px 24px rgba(91,41,59,.2);
142: }
143: .logo::after {
144:   content: "✦"; position: absolute; right: 1%; top: -2%;
145:   font-size: .35em; color: #fff3b0; -webkit-text-stroke: 1px #a56148;
146:   filter: drop-shadow(0 2px 0 #9d4c64); transform: rotate(8deg);
147: }
148: .splash-tagline {
149:   max-width: 500px; font-size: clamp(15px, 1.4vw, 19px); line-height: 1.45;
150:   font-weight: 700; color: #5b3e4c; margin-bottom: 9px;
151: }
152: .splash-copy-small { max-width: 490px; font-size: 12px; line-height: 1.55; color: #765768; margin-bottom: 21px; }
153: .splash-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 14px; }
154: .splash-note { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 9.5px; font-weight: 700; letter-spacing: .03em; color: #815f6c; }
155: .splash-note .dot { width: 3px; height: 3px; border-radius: 50%; background: currentColor; opacity: .55; }
156: 
157: .hero-stage {
158:   position: relative; min-height: min(63vh, 620px);
159:   display: flex; align-items: flex-end; justify-content: center;
160: }
161: .hero-burst {
162:   position: absolute; width: min(590px, 100%); aspect-ratio: 1; left: 50%; top: 48%;
163:   translate: -50% -50%; border-radius: 50%;
164:   background:
165:     repeating-conic-gradient(from 2deg, rgba(255,250,219,.86) 0 7deg, rgba(255,214,185,.45) 7deg 14deg),
166:     radial-gradient(circle, #fff8db 0 18%, #ffd9d6 47%, rgba(255,204,203,.1) 70%);
167:   border: 2px dashed rgba(128, 72, 89, .22);
168:   box-shadow: inset 0 0 0 14px rgba(255,252,232,.32), 0 22px 50px rgba(116, 47, 73, .15);
169:   animation: burst-turn 80s linear infinite;
170:   z-index: 0;
171: }
172: @keyframes burst-turn { to { rotate: 360deg; } }
173: .hero-burst::before {
174:   content: ""; position: absolute; inset: 21%; border-radius: 50%;
175:   background: radial-gradient(circle at 50% 50%, #fff9e8 0 35%, #ffe0cd 68%, rgba(255,208,204,.1) 69%);
176: }
177: .hero-cast {
178:   position: relative; z-index: 3; width: 100%; height: min(60vh, 580px);
179:   display: flex; align-items: flex-end; justify-content: center;
180: }
181: .hero-person {
182:   position: absolute; bottom: 2%;
183:   width: clamp(220px, 24vw, 315px); height: 84%;
184:   filter: drop-shadow(0 16px 18px rgba(94,49,68,.22));
185:   animation: hero-bob 5.5s ease-in-out infinite;
186:   transform-origin: 50% 100%;
187: }
188: .hero-person:nth-child(1) { left: 0; bottom: 1%; width: clamp(195px, 21vw, 280px); rotate: -5deg; animation-delay: -1.5s; }
189: .hero-person:nth-child(2) { left: 50%; translate: -50% 0; width: clamp(240px, 26vw, 345px); z-index: 4; bottom: 0; }
190: .hero-person:nth-child(3) { right: 0; bottom: 3%; width: clamp(195px, 21vw, 280px); rotate: 5deg; animation-delay: -3s; }
191: .hero-person:nth-child(4) { left: 35%; bottom: 22%; width: clamp(160px, 17vw, 225px); z-index: 5; rotate: 7deg; animation-delay: -4s; }
192: @keyframes hero-bob { 50% { transform: translateY(-9px); } }
193: .hero-person::after {
194:   content: ""; position: absolute; left: 13%; right: 13%; bottom: -1%; height: 20px;
195:   background: radial-gradient(ellipse, rgba(98, 47, 69, .23), transparent 67%);
196:   border-radius: 50%;
197: }
198: .hero-portrait {
199:   position: absolute; inset: 0 4% 0;
200:   display: flex; align-items: flex-end; justify-content: center;
201:   border-radius: 44% 44% 24% 24%;
202:   overflow: hidden;
203:   background: linear-gradient(180deg, rgba(255,248,234,.26), rgba(255,211,215,.38));
204:   border: 2px solid rgba(95,52,70,.32);
205:   box-shadow: inset 0 0 0 7px rgba(255,251,240,.23);
206: }
207: .hero-portrait .avatar-svg { height: 116%; width: 118%; transform: translateY(4%); }
208: .hero-center .hero-portrait { border-radius: 46% 46% 22% 22%; background: linear-gradient(180deg, rgba(255,248,217,.2), rgba(255,183,194,.45)); }
209: .hero-person .name-tag {
210:   position: absolute; left: 50%; bottom: -13px; translate: -50%;
211:   z-index: 7; display: inline-flex; align-items: center; gap: 5px;
212:   padding: 6px 11px; border-radius: 999px; white-space: nowrap;
213:   background: #fffaf0; border: 1.5px solid var(--line);
214:   box-shadow: 0 3px 0 rgba(81,59,81,.15);
215:   font-family: var(--font-display); font-size: 11px;
216: }
217: .hero-person .name-tag small { font-family: var(--font-body); font-size: 8px; letter-spacing: .06em; color: var(--ink-soft); text-transform: uppercase; }
218: .hero-sticker {
219:   position: absolute; z-index: 8; display: flex; align-items: center; gap: 8px;
220:   padding: 9px 12px 9px 9px; border-radius: 15px;
221:   background: rgba(255, 251, 242, .92); border: 1.5px solid var(--line);
222:   box-shadow: 0 4px 0 rgba(81,59,81,.12), 0 13px 28px rgba(86,43,65,.15);
223:   backdrop-filter: blur(8px);
224:   animation: sticker-float 6s ease-in-out infinite;
225: }
226: .hero-sticker b { display: block; font-family: var(--font-display); font-size: 10px; line-height: 1.15; }
227: .hero-sticker small { display: block; font-size: 8px; color: var(--ink-soft); margin-top: 2px; }
228: .sticker-icon {
229:   width: 28px; height: 28px; border-radius: 9px;
230:   display: flex; align-items: center; justify-content: center;
231:   background: #ffe3ea; color: #b9476d; font-size: 15px;
232: }
233: .sticker-date { left: -2%; top: 17%; rotate: -4deg; animation-delay: -2s; }
234: .sticker-heart { right: -1%; top: 39%; rotate: 3.5deg; animation-delay: -4s; }
235: .sticker-heart .sticker-icon { background: #ffe6eb; color: #e35a84; }
236: .sticker-cal { right: 3%; bottom: 1%; rotate: -1.5deg; animation-delay: -1s; }
237: .sticker-cal .sticker-icon { background: #fff2c3; color: #a6741d; }
238: @keyframes sticker-float { 50% { translate: 0 -7px; } }
239: .hero-spark { position: absolute; z-index: 9; color: #fff8c7; text-shadow: 0 2px 0 #a25e59; font-size: 24px; animation: twinkle 3.5s ease-in-out infinite; }
240: .hero-spark.s1 { left: 7%; top: 7%; animation-delay: -1s; }
241: .hero-spark.s2 { right: 8%; top: 13%; font-size: 31px; animation-delay: -2.4s; }
242: .hero-spark.s3 { left: 12%; bottom: 30%; font-size: 17px; animation-delay: -.8s; }
243: .hero-spark.s4 { right: 22%; bottom: 18%; font-size: 19px; animation-delay: -3.2s; }
244: 
245: .splash-footer {
246:   position: relative; z-index: 5;
247:   display: flex; justify-content: space-between; align-items: center; gap: 14px;
248:   padding: 12px clamp(22px, 4vw, 62px) max(14px, env(safe-area-inset-bottom));
249:   color: rgba(255, 251, 242, .85); font-size: 9px; font-weight: 800;
250:   letter-spacing: .08em; text-transform: uppercase;
251:   text-shadow: 0 1px 0 rgba(98, 43, 65, .35);
252: }
253: .splash-footer-left { display: flex; align-items: center; gap: 7px; }
254: .splash-footer .mini-heart { color: #ffc3d3; }
255: 
256: @media (max-width: 980px) {
257:   .splash-main { grid-template-columns: 1fr; padding-top: 2px; }
258:   .splash-copy { max-width: 620px; margin: 0 auto; text-align: center; justify-items: center; }
259:   .splash-kicker, .splash-actions { justify-content: center; }
260:   .logo { margin-left: 0; }
261:   .logo-hollow { margin-left: 0; }
262:   .splash-tagline, .splash-copy-small { margin-left: auto; margin-right: auto; }
263:   .splash-note { justify-content: center; }
264:   .hero-stage { min-height: 430px; margin-top: -10px; }
265:   .hero-cast { height: 440px; }
266:   .hero-person { width: 240px; }
267:   .hero-person:nth-child(1), .hero-person:nth-child(3) { width: 205px; }
268:   .hero-person:nth-child(2) { width: 255px; }
269:   .hero-person:nth-child(4) { width: 170px; }
270:   .sticker-date { left: 3%; top: 10%; }
271:   .sticker-heart { right: 2%; top: 34%; }
272:   .sticker-cal { bottom: 0; }
273: }
274: @media (max-width: 640px) {
275:   .splash-nav { padding: 14px 16px; }
276:   .splash-brand .brand-word { font-size: 11px; }
277:   .splash-meta .meta-pill:first-child { display: none; }
278:   .splash-main { padding: 0 16px 15px; gap: 0; }
279:   .logo { font-size: clamp(57px, 16vw, 80px); }
280:   .splash-tagline { font-size: 14px; }
281:   .splash-copy-small { font-size: 11px; }
282:   .splash-actions { gap: 9px; }
283:   .btn-hero { min-width: 132px; min-height: 48px; }
284:   .hero-stage { min-height: 370px; margin-top: -2px; }
285:   .hero-cast { height: 370px; }
286:   .hero-person:nth-child(1), .hero-person:nth-child(3) { width: 165px; bottom: 4%; }
287:   .hero-person:nth-child(2) { width: 205px; }
288:   .hero-person:nth-child(4) { width: 140px; bottom: 22%; left: 28%; }
289:   .hero-person .name-tag { font-size: 9px; padding: 5px 8px; }
290:   .hero-person .name-tag small { display: none; }
291:   .sticker-date { display: none; }
292:   .sticker-heart { right: -4px; top: 32%; transform: scale(.82); }
293:   .sticker-cal { right: -4px; bottom: 0; transform: scale(.8); transform-origin: right bottom; }
294:   .splash-footer { justify-content: center; font-size: 8px; }
295:   .splash-footer-right { display: none; }
296: }

